            /// <summary>
            /// 3D 화면을 캡처하는 메인 함수
            /// </summary>
            /// <param name="x">시작 X좌표 (기본값: 0)</param>
            /// <param name="y">시작 Y좌표 (기본값: 0)</param>
            /// <param name="width">캡처 너비 (기본값: 0 = 전체)</param>
            /// <param name="height">캡처 높이 (기본값: 0 = 전체)</param>
            /// <returns>캡처된 Bitmap</returns>
            public Bitmap Capture(int x = 0, int y = 0, int width = 0, int height = 0)
            {
                // 뷰포트 크기 가져오기
                int[] viewport = new int[4];
                Gl.glGetIntegerv(Gl.GL_VIEWPORT, viewport);

                // 크기 자동 설정
                if (width == 0) width = viewport[2] - x;
                if (height == 0) height = viewport[3] - y;
                if (width <= 0 || height <= 0) return null;

                // 픽셀 데이터 읽기
                //   주의: GL_PACK_ALIGNMENT 기본값(4) 상태에서 GL_RGB 를 읽으면 행이
                //   4바이트 배수로 패딩되어, 너비가 4의 배수가 아닐 때 배열 밖까지
                //   기록해 관리 힙을 손상시킨다(지연된 FatalExecutionEngineError의 원인).
                //   → 읽기 전 1로 내리고, 다른 코드가 기본값을 기대할 수 있으므로 복원.
                Gl.glPixelStorei(Gl.GL_PACK_ALIGNMENT, 1);
                byte[] pixels = new byte[width * height * 3];
                Gl.glReadPixels(x, y, width, height, Gl.GL_RGB, Gl.GL_UNSIGNED_BYTE, pixels);
                Gl.glPixelStorei(Gl.GL_PACK_ALIGNMENT, 4);

                // Bitmap 생성
                Bitmap bitmap = new Bitmap(width, height, PixelFormat.Format24bppRgb);
                BitmapData data = bitmap.LockBits(new Rectangle(0, 0, width, height),
                                                 ImageLockMode.WriteOnly, PixelFormat.Format24bppRgb);

                // 픽셀 데이터 복사 (Y축 뒤집기 + RGB→BGR 변환)
                //   Bitmap 내부 버퍼는 행마다 Stride(4바이트 정렬) 간격이므로
                //   반드시 data.Stride 기준으로 써야 한다 (width*3 로 쓰면 버퍼 침범).
                byte[] rowBuf = new byte[width * 3];
                for (int row = 0; row < height; row++)
                {
                    int srcRow = (height - 1 - row) * width * 3;
                    for (int col = 0; col < width; col++)
                    {
                        int s = srcRow + col * 3;
                        int d = col * 3;
                        rowBuf[d] = pixels[s + 2];     // B
                        rowBuf[d + 1] = pixels[s + 1]; // G
                        rowBuf[d + 2] = pixels[s];     // R
                    }
                    Marshal.Copy(rowBuf, 0,
                        new IntPtr(data.Scan0.ToInt64() + (long)row * data.Stride), width * 3);
                }

                bitmap.UnlockBits(data);
                return bitmap;
            }

            /// <summary>
            /// 전체 화면 캡처 (가장 간단한 사용법)
            /// </summary>
            public Bitmap CaptureAll()
            {
                return Capture();
            }

            /// <summary>
            /// 사각형 영역 캡처
            /// </summary>
            public Bitmap CaptureRect(Rectangle rect)
            {
                return Capture(rect.X, rect.Y, rect.Width, rect.Height);
            }

