            private Form m_frmOffscreen = null;

            /// <summary>
            /// 보이지 않는 창으로 3D를 초기화합니다. Python에서 사용하기 위한 함수입니다.
            /// 사용 후 반드시 DestroyOffscreen()을 호출하세요.
            ///
            /// [Python 사용 예시]
            ///   c3d = Ojw.C3D()
            ///   c3d.InitOffscreen(400, 300)
            ///   c3d.MakeDHSkeleton(10.0, Color.White, dh_string)
            ///   c3d.SetData(11, 45.0)
            ///   c3d.OjwDraw()
            ///   png_bytes = c3d.CaptureToBytes()       # PNG byte[]
            ///   # 또는
            ///   c3d.CaptureToFile("frame.png")         # 파일로 저장
            ///   c3d.DestroyOffscreen()
            /// </summary>
            public void InitOffscreen(int nWidth = 400, int nHeight = 300)
            {
                if (m_frmOffscreen != null) DestroyOffscreen();

                m_frmOffscreen = new Form();
                m_frmOffscreen.FormBorderStyle = FormBorderStyle.None;
                m_frmOffscreen.ShowInTaskbar = false;
                m_frmOffscreen.StartPosition = FormStartPosition.Manual;
                m_frmOffscreen.Location = new Point(-10000, -10000);
                m_frmOffscreen.Size = new Size(nWidth, nHeight);
                m_frmOffscreen.Show();

                // Python 등 외부 메시지 루프 환경에서 Form 생성 메시지를 처리
                Application.DoEvents();

                Init(m_frmOffscreen);

                // OpenGL 컨텍스트 초기화를 위한 메시지 처리
                Application.DoEvents();

                SetStandardAxis(true);
                Enable_Light(true);
            }

            /// <summary>
            /// InitOffscreen()으로 만든 오프스크린 창을 해제합니다.
            /// </summary>
            public void DestroyOffscreen()
            {
                if (m_frmOffscreen != null)
                {
                    try { DInit(); } catch { }
                    try { m_frmOffscreen.Close(); m_frmOffscreen.Dispose(); } catch { }
                    m_frmOffscreen = null;
                }
            }

            /// <summary>
            /// 현재 3D 화면을 PNG 바이트 배열로 캡처합니다.
            /// Python에서 PIL.Image.open(io.BytesIO(bytes(png_bytes)))로 사용할 수 있습니다.
            /// </summary>
            public byte[] CaptureToBytes()
            {
                Application.DoEvents();
                OjwDraw();
                Application.DoEvents();
                using (Bitmap bmp = CaptureAll())
                using (var ms = new System.IO.MemoryStream())
                {
                    bmp.Save(ms, System.Drawing.Imaging.ImageFormat.Png);
                    return ms.ToArray();
                }
            }

            /// <summary>
            /// 현재 3D 화면을 파일로 저장합니다 (.png, .jpg, .bmp).
            /// </summary>
            public void CaptureToFile(string filePath)
            {
                Application.DoEvents();
                OjwDraw();
                Application.DoEvents();
                using (Bitmap bmp = CaptureAll())
                {
                    string ext = System.IO.Path.GetExtension(filePath).ToLower();
                    System.Drawing.Imaging.ImageFormat fmt = System.Drawing.Imaging.ImageFormat.Png;
                    if (ext == ".jpg" || ext == ".jpeg") fmt = System.Drawing.Imaging.ImageFormat.Jpeg;
                    else if (ext == ".bmp") fmt = System.Drawing.Imaging.ImageFormat.Bmp;
                    bmp.Save(filePath, fmt);
                }
            }

            /// <summary>
            /// robot_config.txt의 [DH] 섹션을 읽어 3D 스켈레톤을 생성합니다.
            /// Python에서 한 줄로 로봇 모델을 로드할 수 있습니다.
            ///
            /// [Python 사용 예시]
            ///   c3d.LoadDH("robot_config.txt")
            /// </summary>
            public void LoadDH(string configPath, float fSize = 10.0f)
            {
                if (!System.IO.File.Exists(configPath)) return;

                string section = null;
                var dhLines = new System.Collections.Generic.List<string>();
                foreach (var rawLine in System.IO.File.ReadAllLines(configPath, System.Text.Encoding.UTF8))
                {
                    string s = rawLine.Trim();
                    // 주석 제거
                    int commentIdx = s.IndexOf("//");
                    if (commentIdx >= 0) s = s.Substring(0, commentIdx).Trim();
                    if (string.IsNullOrEmpty(s) || s.StartsWith("#")) continue;
                    if (s.StartsWith("[") && s.EndsWith("]") && !s.Contains(","))
                    {
                        section = s.Substring(1, s.Length - 2);
                        continue;
                    }
                    if (section == "DH")
                    {
                        // [A,D,Theta,Alpha],[Axis,Dir,Init] → A,D,Theta,Alpha,Axis,Dir,Init
                        string converted = s.Replace("[", "").Replace("]", "");
                        dhLines.Add(converted);
                    }
                }

                if (dhLines.Count == 0) return;
                string dhString = string.Join("\r\n", dhLines.ToArray());

                Application.DoEvents();

                TextBox txt = null;
                m_CHeader.strDrawModel = MakeDHSkeleton(true, true, fSize, Color.White, dhString,
                    0, 0, 0, 0, 0, 0, 0, ref txt);

                // DH 로드 후 한 번 그려서 초기 상태 확인
                Application.DoEvents();
                OjwDraw();
                Application.DoEvents();
            }

