            // IK 반복이 CalcF → GetData_Forward 를 수천 번 부르므로 (TRAC-IK 1회에
            // 반복×(관절+1)회) 매 호출 double[256] 할당이 GC 지연의 주범이었다.
            // 스레드별 버퍼 재사용 — 전 요소를 덮어쓰므로 Clear 불필요. (2026-08-13)
            [ThreadStatic] private static double[] s_adFkMotBuf;
            private static double[] FkMotBuf()
            {
                double[] ad = s_adFkMotBuf;
                if (ad == null) ad = s_adFkMotBuf = new double[256];
                return ad;
            }
            public bool GetData_Forward(int nNum, out double dX, out double dY, out double dZ)
            {
                int i;
                double[] dcolX;
                double[] dcolY;
                double[] dcolZ;

                double[] adMot = FkMotBuf();
                for (i = 0; i < 256; i++) adMot[i] = (double)GetData(i);
                return Ojw.CKinematics.CForward.CalcKinematics(m_CHeader.pDhParamAll[nNum], adMot, out dcolX, out dcolY, out dcolZ, out dX, out dY, out dZ);
            }
            // end-effector 위치 + 회전행렬(3열: 프레임 X/Y/Z 축벡터) 반환 — full SE(3) FK.
            //   커널 CalcKinematics 가 이미 회전 3열(dcolX/Y/Z)을 계산하므로 그대로 노출.
            //   colX/colY/colZ 는 각각 end-effector 프레임의 X/Y/Z 축 (월드 좌표계 방향벡터).
            public bool GetData_Forward_Pose(int nNum,
                out double dX, out double dY, out double dZ,
                out double[] colX, out double[] colY, out double[] colZ)
            {
                int i;
                double[] adMot = FkMotBuf();
                for (i = 0; i < 256; i++) adMot[i] = (double)GetData(i);
                return Ojw.CKinematics.CForward.CalcKinematics(m_CHeader.pDhParamAll[nNum], adMot,
                    out colX, out colY, out colZ, out dX, out dY, out dZ);
            }

            // CalcF 의 pose 버전 — 현재 관절값 기준 end-effector 위치 + 회전 3열
            public void CalcF_Pose(int nFunctionNumber, bool bLimitFunctionNumber,
                out float px, out float py, out float pz,
                out float[] colX, out float[] colY, out float[] colZ)
            {
                Ojw.CKinematics.CForward.SetCalcLimit_Axis(-1); // 전체 체인 (끝점까지)
                if (bLimitFunctionNumber) Ojw.CKinematics.CForward.SetCalcLimit_FunctionNumber(nFunctionNumber);
                double dX, dY, dZ;
                double[] dcolX, dcolY, dcolZ;
                GetData_Forward_Pose(nFunctionNumber, out dX, out dY, out dZ, out dcolX, out dcolY, out dcolZ);
                px = (float)dX; py = (float)dY; pz = (float)dZ;
                colX = new float[] { (float)dcolX[0], (float)dcolX[1], (float)dcolX[2] };
                colY = new float[] { (float)dcolY[0], (float)dcolY[1], (float)dcolY[2] };
                colZ = new float[] { (float)dcolZ[0], (float)dcolZ[1], (float)dcolZ[2] };
            }

            public bool GetData_Forward_LastOf(int nNum, out double dX, out double dY, out double dZ)
            {
                int i;
                double[] dcolX;
                double[] dcolY;
                double[] dcolZ;

                double[] adMot = FkMotBuf();
                for (i = 0; i < 256; i++) adMot[i] = (double)GetData(i);
                return Ojw.CKinematics.CForward.CalcKinematics_LastOf(m_CHeader.pDhParamAll[nNum], adMot, out dcolX, out dcolY, out dcolZ, out dX, out dY, out dZ);  
            }

            // return MotorCount, and ...
            public int GetData_Inverse(int nNum, double dX, double dY, double dZ, double [] adV, out int[] anMotorID, out double[] adValue)
            {
                // 집어넣기 전에 내부 메모리를 클리어 한다.
                Ojw.CKinematics.CInverse.SetValue_ClearAll(ref GetHeader_pSOjwCode()[nNum]);
                Ojw.CKinematics.CInverse.SetValue_X(dX);
                Ojw.CKinematics.CInverse.SetValue_Y(dY);
                Ojw.CKinematics.CInverse.SetValue_Z(dZ);

                if (adV != null)
                {
                    for (int i = 0; i < adV.Length; i++)
                    {
                        Ojw.CKinematics.CInverse.SetValue_V(i, adV[i]);
                    }
                }

                // 현재의 모터각을 전부 집어 넣도록 한다.
                for (int i = 0; i < m_CHeader.nMotorCnt; i++)
                {
                    // 모터값을 3D에 넣어주고
                    //SetData(i, Ojw.CConvert.StrToFloat(m_txtAngle[i].Text));
                    // 그 값을 꺼내 수식 계산에 넣어준다.
                    Ojw.CKinematics.CInverse.SetValue_Motor(i, GetData(i));
                }

                // 실제 수식계산 (C3d도 함께 설정)
                Ojw.CKinematics.CInverse.SetCodeArray(GetHeader_pSOjwCode(), this);
                Ojw.CKinematics.CInverse.CalcCode(ref GetHeader_pSOjwCode()[nNum]);


                // 나온 결과값을 옮긴다.
                int nMotCnt = GetHeader_pSOjwCode()[nNum].nMotor_Max;
                if (nMotCnt <= 0)
                {
                    anMotorID = null;
                    adValue = null;
                    return 0;
                }
                anMotorID = new int[nMotCnt];
                adValue = new double[nMotCnt];
                for (int i = 0; i < nMotCnt; i++)
                {
                    anMotorID[i] = GetHeader_pSOjwCode()[nNum].pnMotor_Number[i];
                    adValue[i] = Ojw.CKinematics.CInverse.GetValue_Motor(anMotorID[i]);
                }
                return nMotCnt;
            }
            public int GetData_Inverse(int nNum, double dX, double dY, double dZ, out int [] anMotorID, out double [] adValue)
            {
                return GetData_Inverse(nNum, dX, dY, dZ, null, out anMotorID, out adValue);
#if false
