            public void MakeAll(int nKinematicsIndex, string strDesingPart_For_Calc, string strDesignFull_For_Drawing = "", float fSize = 10.0f, int nInverseKinematics_AfterCalc = -1, string strInverse_AfterCalc = "") // 
            {
