            // === 트랙 벨트 변환용 풀리 정보 (2-풀리 Phase 1+2 알고리즘) ===
            // `?`/`?!` 접두사 라인은 collector → 풀리 정보 누적
            // `/`/`/!` 접두사 라인은 trigger → 누적된 풀리들로 벨트 전체 생성 후 클리어
            private class TrackPulleyUrdf
            {
                public float fX, fY, fR, fDistance;          // 로컬 2D 좌표·반경·세그먼트 간격 (mm)
                public int nMode, nAxis, nDir;
                public string filename;                       // 접두사 제거된 STL 이름
                public uint color;
                public float localPan, localTilt, localSwing; // @ 라인의 로컬 회전 (도)
                public float localTransX, localTransY, localTransZ;
                public double lineOffX, lineOffY, lineOffZ;   // 수집 시점의 체인 세계 오프셋 (m)
                public double relX, relY, relZ;               // 마지막 joint 이후의 상대 오프셋 (m)
                public double[] R;                            // 수집 시점의 체인 3x3 회전 행렬
            }
            private List<TrackPulleyUrdf> m_lstTrackPulleysUrdf = new List<TrackPulleyUrdf>();

            // === 트랙 벨트 메타데이터 (런타임 Python 스크립트가 세그먼트 흐름 애니메이션에 사용) ===
            public class TrackBeltMetaUrdf
            {
