                        break;
                    case m_strProp_Main3:
                        Prop_Set_Main_Alpha((float)e.ChangedItem.Value);
                        break;
                    case m_strProp_Main4:
                        Prop_Set_Main_Light((bool)e.ChangedItem.Value);
                        break;
                    case m_strProp_Main5:
