            protected override bool ProcessCmdKey(ref Message msg, Keys keyData)
            {
                switch (keyData)
                {
                    #region Keys.Up
                    case Keys.Up:
                        {                            
                            int nDir = 1;
                            m_afLookat_Dir[nDir] += 0.1f;
                            if (m_afLookat_Dir[nDir] > 1.0f) m_afLookat_Dir[nDir] = 1.0f;                         
                        }
                        break;
                    #endregion Keys.Up
                    #region Keys.Down
                    case Keys.Down:
                        {
                            int nDir = 1;
                            m_afLookat_Dir[nDir] -= 0.1f;
                            if (m_afLookat_Dir[nDir] <= -1.0f) m_afLookat_Dir[nDir] = -1.0f;
                        }
                        break;
                    #endregion Keys.Down

                    #region Keys.Left
                    case Keys.Left:
                        {
                            int nDir = 0;
                            m_afLookat_Dir[nDir] += 0.1f;
                            if (m_afLookat_Dir[nDir] > 1.0f) m_afLookat_Dir[nDir] = 1.0f;
                        }
                        break;
                    #endregion Keys.Left
                    #region Keys.Right
                    case Keys.Right:
                        {
                            int nDir = 0;
                            m_afLookat_Dir[nDir] -= 0.1f;
                            if (m_afLookat_Dir[nDir] <= -1.0f) m_afLookat_Dir[nDir] = -1.0f;
                        }
                        break;
                    #endregion Keys.Right
                }
                return base.ProcessCmdKey(ref msg, keyData);
