                public void CalcF(int nFunctionNumber, int nAxis, out float fX, out float fY, out float fZ)
                {
#if false
                    Ojw.CKinematics.CForward.SetCalcLimit_Axis(nAxis); // nAxis 번 모터까지의 위치값 확인

                    double dX, dY, dZ;
