                    fX = (float)dX; fY = (float)dY; fZ = (float)dZ;
#else
                    CalcF(nFunctionNumber, nAxis, false, out fX, out fY, out fZ);
#endif
                }
                public void CalcF(int nFunctionNumber, int nAxis, bool bLimitFunctionNumber, out float fX, out float fY, out float fZ)
                {
                    Ojw.CKinematics.CForward.SetCalcLimit_Axis(nAxis); // nAxis 번 모터까지의 위치값 확인
                    if (bLimitFunctionNumber == true) Ojw.CKinematics.CForward.SetCalcLimit_FunctionNumber(nFunctionNumber);

                    double dX, dY, dZ;
                    GetData_Forward(nFunctionNumber, out dX, out dY, out dZ);
                    fX = (float)dX; fY = (float)dY; fZ = (float)dZ;
                    //Ojw.CMessage.Write("[{0}]Calc X[{1}], Y[{2}], Z[{3}]", nAxis, Ojw.CMath.Round(fX, 1), Ojw.CMath.Round(fY, 1), Ojw.CMath.Round(fZ, 1));
                }
                // 특정 모터, 혹은 FunctionNumber 까지를 a, d 를 다 0 으로 초기화 한 위치 + 초기위치 를 시작 위치로, 거기부터 마지막까지를 최종위치로 하는 함수

                public List<int> m_lstCalcInv_Endpoint = new List<int>();
                public void CalcInv_Endpoint_Clear()
                {
                    m_lstCalcInv_Endpoint.Clear();
                }
                public void CalcInv_Endpoint_Add(int nAxis) { m_lstCalcInv_Endpoint.Add(nAxis); }
                public bool CalcInv_Endpoint_Check() { return (m_lstCalcInv_Endpoint.Count > 1) ? true : false; }
                public float CalcInv_Endpoint_Result()
                {
                    float fRes = 0.0f;
                    int nID = 0;
                    if (CalcInv_Endpoint_Check() == true)
                    {
                        for (int i = 0; i < m_lstCalcInv_Endpoint.Count; i++)
                        {
                            nID = Math.Abs(m_lstCalcInv_Endpoint[i]);
                            fRes += ((m_lstCalcInv_Endpoint[i] < 0) ? -1 : 1) * GetData(nID);
                        }
                    }
                    return fRes;
                }

                public int m_nCalcInv_Mode = 0; // 0 : auto, 1 : Inverse, 2 : Inverse & Reverse, 3 : Inverse & Motor
                public void CalcInv_SetMode(int nMode) { m_nCalcInv_Mode = nMode; } // 0 : auto, 1 : Inverse, 2 : Inverse & Reverse, 3 : Inverse & Motor
                public int m_nCalcInv_IKAlgorithm = 0; // 0: CCD, 1: FABRIK
                public void CalcInv_SetIKAlgorithm(int nAlgorithm) { m_nCalcInv_IKAlgorithm = nAlgorithm; } // 0: CCD, 1: FABRIK

                // 마지막 IK 호출이 실제로 사용한 외부 iter 수 (수렴 시 break 위치, 아니면 nRepeat)
                private int m_nLastCalcInv_Iter = 0;
                private int m_nLastCalcInv2_Iter = 0;
                private int m_nLastCalcInv_FABRIK_Iter = 0;
                private int m_nLastPaperFABRIK_Iter = 0;
                private int m_nLastPaperCCDIK_Iter = 0;
                private int m_nLastWangChenCCDIK_Iter = 0;
                private int m_nLastKenwrightCCDIK_Iter = 0;
                private int m_nLastTracIK_Iter = 0;
                private int m_nLastJacobianDLS_Iter = 0;
                private int m_nLastJacobianEuler_Iter = 0;
                private int m_nLastJacobianIK_Iter = 0;
                public int GetLastIK_Iter() { return m_nLastCalcInv_Iter + m_nLastCalcInv2_Iter; } // DC-CCD: 단일단계 → m_nLastCalcInv2_Iter 는 보통 0
                public int GetLastIK_Iter_FABRIK() { return m_nLastCalcInv_FABRIK_Iter; }
                public int GetLastIK_Iter_PaperFABRIK() { return m_nLastPaperFABRIK_Iter; }
                public int GetLastIK_Iter_PaperCCDIK() { return m_nLastPaperCCDIK_Iter; }
                public int GetLastIK_Iter_WangChenCCDIK() { return m_nLastWangChenCCDIK_Iter; }
                public int GetLastIK_Iter_KenwrightCCDIK() { return m_nLastKenwrightCCDIK_Iter; }
                public int GetLastIK_Iter_TracIK() { return m_nLastTracIK_Iter; }
                public int GetLastIK_Iter_JacobianDLS() { return m_nLastJacobianDLS_Iter; }
                public int GetLastIK_Iter_JacobianEuler() { return m_nLastJacobianEuler_Iter; }
                public int GetLastIK_Iter_JacobianIK() { return m_nLastJacobianIK_Iter; }
                internal void SetLastIK_Iter_JacobianIK(int n) { m_nLastJacobianIK_Iter = n; }

                // ========================================
                // TRAC-IK 안전 옵션 (기본값 = 기존 동작 → 벤치마크/논문 수치 불변)
                //   연속 제어(보행/드래그 tracking) 시 SetTracIK_Continuous(true) 로 프리셋 활성.
                //   정적 단발 계산은 기본값 그대로 두면 기존과 100% 동일.
                // ========================================
                private bool  m_bTracIK_Continuous           = false; // tracking 모드 여부
                private bool  m_bTracIK_DisableRandomRestart = false; // #1 랜덤재시작 금지
                private float m_fTracIK_MaxStepPerCallDeg     = 0.0f;  // #4 호출 간 관절 최대 변화(도), 0=무제한
                private bool  m_bTracIK_RollbackOnFail        = false; // #5 실패 시 초기자세 복원
                private bool  m_bTracIK_ContinuityTieBreak    = false; // #7 solver 동률 시 이전자세 가까운 쪽

                // tracking 프리셋: 랜덤재시작 금지 + 프레임당 변화 제한 + 실패 rollback + 연속성 tie-break
                public void SetTracIK_Continuous(bool b)
                {
                    m_bTracIK_Continuous           = b;
                    m_bTracIK_DisableRandomRestart = b;
                    m_bTracIK_RollbackOnFail       = b;
                    m_bTracIK_ContinuityTieBreak   = b;
                    if (b && m_fTracIK_MaxStepPerCallDeg <= 0.0f) m_fTracIK_MaxStepPerCallDeg = 20.0f;
                    if (!b) m_fTracIK_MaxStepPerCallDeg = 0.0f;
                }
                public bool GetTracIK_Continuous() { return m_bTracIK_Continuous; }
                public void SetTracIK_DisableRandomRestart(bool b) { m_bTracIK_DisableRandomRestart = b; }
                public void SetTracIK_MaxStepPerCallDeg(float deg) { m_fTracIK_MaxStepPerCallDeg = deg; }
                public void SetTracIK_RollbackOnFail(bool b) { m_bTracIK_RollbackOnFail = b; }
                public void SetTracIK_ContinuityTieBreak(bool b) { m_bTracIK_ContinuityTieBreak = b; }

                private static bool IkFinite(float v) { return !float.IsNaN(v) && !float.IsInfinity(v); }

                // 드래그 IK 알고리즘 타입 (CallInverse nType과 동일한 매핑)
                //   0: Formula (사용자 수식), 1: Ojw CCD-IK, 2: TRAC-IK,
                //   3: PaperCCD, 4: WangChen, 5: Kenwright, 6: FABRIK(Paper),
                //   7: Paper Jacobian DLS, 8: Paper Jacobian Euler,
                //   11: JacobianDLS PosOnly, 12: Jacobian+Tool, 13: Jacobian+Tool Global
                // 기본값 = 2 (TRAC-IK): 특이점 강건성이 높아 드래그에 가장 안정적
                public int m_nDragIKType = 2;
                public void SetDragIKType(int nType) { m_nDragIKType = nType; }
                public int GetDragIKType() { return m_nDragIKType; }

                // ========================================
                // IK Lock — eDH 의 Type=5 마커로 등록된 "FK 는 적용, IK 만 제외" 모터 집합
                //   key   = funcNum (-1 = 모든 IK 수식에 적용되는 글로벌 lock)
                //   value = lock 된 모터 ID 집합
                //   wildcards: eDH 의 Num=255 → -1 (글로벌) 로 저장
                // ========================================
                private Dictionary<int, HashSet<int>> m_dictIKLock = new Dictionary<int, HashSet<int>>();

                /// <summary>모터 한 개를 특정 IK 수식의 active list 에서 제외 등록. funcNum=-1 또는 255 → 글로벌(모든 IK 에서 제외)</summary>
                public void SetIKLock(int nMotorID, int nFunctionNumber)
                {
                    if (nMotorID < 0) return;
                    int key = (nFunctionNumber == 255) ? -1 : nFunctionNumber;
                    HashSet<int> set;
                    if (m_dictIKLock.TryGetValue(key, out set) == false)
                    {
                        set = new HashSet<int>();
                        m_dictIKLock[key] = set;
                    }
                    set.Add(nMotorID);
                }

                /// <summary>등록된 IK lock 모두 해제</summary>
                public void ClearIKLock() { m_dictIKLock.Clear(); }

                /// <summary>특정 IK 수식에 대한 lock 만 해제</summary>
                public void ClearIKLock(int nFunctionNumber)
                {
                    int key = (nFunctionNumber == 255) ? -1 : nFunctionNumber;
                    if (m_dictIKLock.ContainsKey(key)) m_dictIKLock.Remove(key);
                }

                /// <summary>현재 등록된 lock 모터 조회 (글로벌+해당 funcNum 합집합)</summary>
                public int[] GetIKLockedMotors(int nFunctionNumber)
                {
                    HashSet<int> locked = new HashSet<int>();
                    HashSet<int> setG;
                    if (m_dictIKLock.TryGetValue(-1, out setG)) foreach (int id in setG) locked.Add(id);
                    HashSet<int> setF;
                    if (m_dictIKLock.TryGetValue(nFunctionNumber, out setF)) foreach (int id in setF) locked.Add(id);
                    int[] arr = new int[locked.Count];
                    int idx = 0; foreach (int id in locked) { arr[idx++] = id; }
                    return arr;
                }

                /// <summary>해당 funcNum 의 IK 알고리즘에 넘길 active motor list 를 계산. DH chain 모터 ∖ (글로벌 lock ∪ funcNum lock)</summary>
                private int[] GetActiveMotorsForIK(int nFunctionNumber)
                {
                    // 더미축(255) 포함 반환 — IK 코어의 "마지막 모터 제외" 정책이 더미를 제외하도록.
                    //   더미 없는 DH 는 GetMotors_With_Dummy() == GetMotors() 이므로 기존 동작과 동일.
                    //   더미 있는 DH 는 마지막 실제 모터 대신 더미(255)가 제외됨 (off-by-one 해소).
                    int[] all = (m_CHeader != null && m_CHeader.pDhParamAll != null && m_CHeader.pDhParamAll[nFunctionNumber] != null)
                        ? m_CHeader.pDhParamAll[nFunctionNumber].GetMotors_With_Dummy()
                        : null;
                    if (all == null) return null;
                    // 빠른 분기: lock 비어있으면 그대로 반환 (외부 사용자 동작 100% 보존)
                    if (m_dictIKLock.Count == 0) return all;

                    HashSet<int> locked = new HashSet<int>();
                    HashSet<int> setG;
                    if (m_dictIKLock.TryGetValue(-1, out setG)) foreach (int id in setG) locked.Add(id);
                    HashSet<int> setF;
                    if (m_dictIKLock.TryGetValue(nFunctionNumber, out setF)) foreach (int id in setF) locked.Add(id);
                    if (locked.Count == 0) return all;

                    List<int> active = new List<int>(all.Length);
                    for (int i = 0; i < all.Length; i++)
                    {
                        if (locked.Contains(all[i]) == false) active.Add(all[i]);
                    }
                    return active.ToArray();
                }

                #region Delta(병렬) IK — $deltaik 등록 번호는 닫힌해로 직접 해석 (2026-08-14)
                // DH 텍스트 문법: $deltaik, N, m1, m2, m3, 윗판Rad, 윗링크, 아래링크, 아래판Rad [, x0, y0, z0]
                //   N = [2,N] 으로 마킹한 IK 번호. 드래그/Go/AutoIK 진입 시 직렬 알고리즘 대신
                //   Delta_Parallel_InverseKinematics 닫힌해로 즉시 풀어 모터 m1~m3 에 기입한다.
                //   기하 해석은 getdelta/CDelta 와 동일 (Rad = Trossen 변길이 규약). x0~z0 = 베이스 원점 월드 오프셋.
                private class CDeltaIkDef
                {
                    public int nMot0, nMot1, nMot2;
                    public float fRadUp, fLenUp, fLenDown, fRadDown;
                    public float fX0, fY0, fZ0;
                }
                private Dictionary<int, CDeltaIkDef> m_dictDeltaIK = new Dictionary<int, CDeltaIkDef>();
                // ── 이상 상황 전용 로그 (%TEMP%\ojw_deltaik_debug.log, 세션당 400줄 제한) ──
                //   평시에는 침묵. $deltaik 기하 이상 등 조용히 실패하는 계열의 사고만 기록 (2026-08-14 사고 추적용 잔류)
                private static int s_nDeltaIkLogCnt = 0;
                private static void DeltaIK_Log(string strMsg)
                {
                    try
                    {
                        if (s_nDeltaIkLogCnt++ > 400) return;
                        System.IO.File.AppendAllText(
                            System.IO.Path.Combine(System.IO.Path.GetTempPath(), "ojw_deltaik_debug.log"),
                            DateTime.Now.ToString("HH:mm:ss.fff ") + strMsg + "\r\n");
                    }
                    catch { }
                }
                public void ClearDeltaIK() { m_dictDeltaIK.Clear(); }
                public void SetDeltaIK(int nFuncNum, int nMot0, int nMot1, int nMot2,
                    float fRadUp, float fLenUp, float fLenDown, float fRadDown,
                    float fX0 = 0, float fY0 = 0, float fZ0 = 0)
                {
                    // 기하 검증 — 파괴된 $deltaik ("링크 길이 2mm" 등)로 등록되면 모든 IK 가
                    // 조용히 실패해 원인 추적이 어렵다 (2026-08-14: 체인 매퍼가 $ 라인을 덮어쓴 실사고)
                    if ((fRadUp <= 0) || (fLenUp <= 0) || (fLenDown <= 0) || (fRadDown < 0))
                    {
                        DeltaIK_Log(string.Format("SetDeltaIK REJECTED N={0} geo=({1},{2},{3},{4}) — 기하 이상",
                            nFuncNum, fRadUp, fLenUp, fLenDown, fRadDown));
                        return;
                    }
                    CDeltaIkDef sDef = new CDeltaIkDef();
                    sDef.nMot0 = nMot0; sDef.nMot1 = nMot1; sDef.nMot2 = nMot2;
                    sDef.fRadUp = fRadUp; sDef.fLenUp = fLenUp; sDef.fLenDown = fLenDown; sDef.fRadDown = fRadDown;
                    sDef.fX0 = fX0; sDef.fY0 = fY0; sDef.fZ0 = fZ0;
                    m_dictDeltaIK[nFuncNum] = sDef;
                }
                public bool IsDeltaIK(int nFuncNum) { return m_dictDeltaIK.ContainsKey(nFuncNum); }
                /// <summary>등록된 델타 IK 면 현재 모터값의 이펙터 위치(FK)를 돌려준다 — 드래그 시작점용.</summary>
                public bool DeltaIK_TryGetFK(int nFuncNum, out float fX, out float fY, out float fZ)
                {
                    fX = fY = fZ = 0;
                    CDeltaIkDef sDef;
                    if (m_dictDeltaIK.TryGetValue(nFuncNum, out sDef) == false) return false;
                    Ojw.CMath.Delta_Parallel_Init(sDef.fRadUp, sDef.fLenUp, sDef.fLenDown, sDef.fRadDown);
                    double dX, dY, dZ;
                    if (Ojw.CMath.Delta_Parallel_ForwardKinematics(GetData(sDef.nMot0), GetData(sDef.nMot1), GetData(sDef.nMot2), out dX, out dY, out dZ) == false) return false;
                    fX = (float)dX + sDef.fX0; fY = (float)dY + sDef.fY0; fZ = (float)dZ + sDef.fZ0;
                    return true;
                }
                /// <summary>등록된 델타 IK 면 닫힌해로 풀어 모터 3개에 기입.
                /// 등록 번호면 작업공간 밖이어도 true (모터 유지, 직렬 IK 로 넘기지 않음) — 미등록만 false.</summary>
                public bool DeltaIK_TrySolve(int nFuncNum, float fX, float fY, float fZ)
                {
                    CDeltaIkDef sDef;
                    if (m_dictDeltaIK.TryGetValue(nFuncNum, out sDef) == false) return false;
                    // 목표 좌표가 오염(NaN/Inf)이면 무시 — 모터 보호 (m_dPos 가 미확정 픽 상태에서 쓰레기일 수 있음)
                    if (float.IsNaN(fX) || float.IsInfinity(fX) ||
                        float.IsNaN(fY) || float.IsInfinity(fY) ||
                        float.IsNaN(fZ) || float.IsInfinity(fZ)) return true;
                    Ojw.CMath.Delta_Parallel_Init(sDef.fRadUp, sDef.fLenUp, sDef.fLenDown, sDef.fRadDown);
                    double dA0, dA1, dA2;
                    if (Ojw.CMath.Delta_Parallel_InverseKinematics(fX - sDef.fX0, fY - sDef.fY0, fZ - sDef.fZ0, out dA0, out dA1, out dA2) == true)
                    {
                        // 닫힌해 결과도 유한할 때만 기입 (NaN 모터값 = 3D 전체 소멸 실사고 2026-08-14)
                        if (double.IsNaN(dA0) == false && double.IsInfinity(dA0) == false &&
                            double.IsNaN(dA1) == false && double.IsInfinity(dA1) == false &&
                            double.IsNaN(dA2) == false && double.IsInfinity(dA2) == false)
                        {
                            SetData(sDef.nMot0, (float)dA0);
                            SetData(sDef.nMot1, (float)dA1);
                            SetData(sDef.nMot2, (float)dA2);
                        }
                    }
                    return true;
                }
                #endregion Delta(병렬) IK

                // 자동 IK 기본 알고리즘 (역기구학 수식 미입력 시 사용)
                // 0: TRAC-IK (ROS) → DC-CCD fallback
                // 1: DC-CCD only
                // 2: TRAC-IK only (fallback 없음)
                // 3: Ojw FABRIK
                // 4: Probe CCD (구 "Paper CCD-IK")
                // 5: WangChen CCD
                // 6: Kenwright CCD
                // 7: Paper FABRIK
                // 8: Paper Jacobian DLS
                private int m_nAutoIK = 0;
                public void SetAutoIK(int nType) { m_nAutoIK = nType; }
                public int GetAutoIK() { return m_nAutoIK; }

                /// <summary>
                /// 자동 IK 실행 (역기구학 수식 미입력 시 호출)
                /// SetAutoIK()로 기본 알고리즘 변경 가능
                /// </summary>
                public bool AutoIK(int nFuncNum, float fX, float fY, float fZ)
                {
                    if (DeltaIK_TrySolve(nFuncNum, fX, fY, fZ)) return true; // 델타(병렬) IK 우선
                    switch (m_nAutoIK)
                    {
                        case 0: // TRAC-IK → Ojw CCD fallback
                            if (TracIK(nFuncNum, fX, fY, fZ, 1000, 0.001f)) return true;
                            CalcInv(nFuncNum, GetHeader_pDhParamAll()[nFuncNum].GetMotors_With_Dummy(), fX, fY, fZ, 1000, 0.001f);
                            return true;
                        case 1: // Ojw CCD-IK only
                            CalcInv(nFuncNum, GetHeader_pDhParamAll()[nFuncNum].GetMotors_With_Dummy(), fX, fY, fZ, 1000, 0.001f);
                            return true;
                        case 2: // TRAC-IK only
                            return TracIK(nFuncNum, fX, fY, fZ, 1000, 0.001f);
                        case 3: // Ojw FABRIK
                            OjwFABRIK(nFuncNum, fX, fY, fZ, 1000, 0.001f);
                            return true;
                        case 4: // Probe CCD (구 "Paper CCD-IK")
                            PaperCCDIK(nFuncNum, fX, fY, fZ, 1000, 0.001f);
                            return true;
                        case 5: // WangChen CCD
                            WangChenCCDIK(nFuncNum, fX, fY, fZ, 1000, 0.001f);
                            return true;
                        case 6: // Kenwright CCD
                            KenwrightCCDIK(nFuncNum, fX, fY, fZ, 1000, 0.001f);
                            return true;
                        case 7: // Paper FABRIK
                            PaperFABRIK(nFuncNum, fX, fY, fZ, 1000, 0.001f);
                            return true;
                        case 8: // Paper Jacobian DLS
                            return PaperJacobianDLS(nFuncNum, fX, fY, fZ);
                        default:
                            CalcInv(nFuncNum, GetHeader_pDhParamAll()[nFuncNum].GetMotors_With_Dummy(), fX, fY, fZ, 1000, 0.001f);
                            return true;
                    }
                }
                public void CalcF_LastOf(int nFunctionNumber, int nAxis, bool bLimitFunctionNumber, out float fX, out float fY, out float fZ)
                {
                    Ojw.CKinematics.CForward.SetCalcLimit_Axis(nAxis); // nAxis 번 모터까지의 위치값 확인
                    if (bLimitFunctionNumber == true) Ojw.CKinematics.CForward.SetCalcLimit_FunctionNumber(nFunctionNumber);

                    double dX, dY, dZ;
                    GetData_Forward_LastOf(nFunctionNumber, out dX, out dY, out dZ);
                    fX = (float)dX; fY = (float)dY; fZ = (float)dZ;
                    //Ojw.CMessage.Write("[{0}]Calc X[{1}], Y[{2}], Z[{3}]", nAxis, Ojw.CMath.Round(fX, 1), Ojw.CMath.Round(fY, 1), Ojw.CMath.Round(fZ, 1));
                }
                public int[] CalcInv_MotorIDs(int nFunctionNumber) { return GetHeader_pDhParamAll()[nFunctionNumber].GetMotors(); }
                // 결과값은 m_C3d.GetData(ID) 로 가져오면 됨
                public float[] CalcInv(int nFunctionNumber, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f) { int[] motors = GetActiveMotorsForIK(nFunctionNumber); if (motors == null) return null; return CalcInv(nFunctionNumber, motors, fX, fY, fZ, nRepeat, fCutline); }
                //public void CalcInv(int nFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                //{
                //    float[] afRes_Angles;
                //    CalcInv(nFunctionNumber, anMotorIDs, fX, fY, fZ, out afRes_Angles, nRepeat, fCutline);
                //}
                public float[] CalcInv(int nFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    return CalcInv(nFunctionNumber, true, anMotorIDs, fX, fY, fZ, nRepeat, fCutline);
                }
                public float[] CalcInv(int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    // FABRIK 알고리즘 선택 시 분기
                    if (m_nCalcInv_IKAlgorithm == 1)
                        return CalcInv_FABRIK(nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline);

                    m_nLastCalcInv_Iter = 0;
                    m_nLastCalcInv2_Iter = 0;

                    int nID;
                    int nCnt = anMotorIDs.Length;

                    //float [] afRes_Angles = new float[nCnt];
                    int nPos = nCnt;
                    float fX0 = fX, fY0 = fY, fZ0 = fZ;
                    float fXc, fYc, fZc;
                    float fXp, fYp, fZp;
                    float fAngle0 = 0;
                    float fP, fN, fC;
                    float fAngle, fAngle1, fAngle2;
                    List<float> lstAngles = new List<float>();
                    for (int i = 0; i < nCnt; i++)
                        lstAngles.Add(GetData(anMotorIDs[i]));
                    float fRes = 0.0f;

                    float fX1, fY1, fZ1;
                    float fX2, fY2, fZ2;
                    CalcF(nFunctionNumber, -1, true, out fX1, out fY1, out fZ1);

                    if (m_bIgnoreCheckInit_CalcInv == false)
                    {
                        // 방향 제한 확인
                        CalcF(nFunctionNumber, -1, false, out fX0, out fY0, out fZ0);
                        bool bX = false;
                        bool bY = false;
                        bool bZ = false;
                        for (int i = 0; i < anMotorIDs.Length; i++)
                        {
                            if ((bX == true) && (bY == true) && (bZ == true)) break;

                            float fVal = GetData(anMotorIDs[i]);
                            SetData(anMotorIDs[i], fVal + 10);
                            CalcF(nFunctionNumber, -1, false, out fXp, out fYp, out fZp);
                            if (bX == false) { if (fX0 != fXp) { bX = true; } }
                            if (bY == false) { if (fY0 != fYp) { bY = true; } }
                            if (bZ == false) { if (fZ0 != fZp) { bZ = true; } }
                            SetData(anMotorIDs[i], fVal - 10);
                            CalcF(nFunctionNumber, -1, false, out fXp, out fYp, out fZp);
                            if (bX == false) { if (fX0 != fXp) { bX = true; } }
                            if (bY == false) { if (fY0 != fYp) { bY = true; } }
                            if (bZ == false) { if (fZ0 != fZp) { bZ = true; } }
                            SetData(anMotorIDs[i], fVal);
                        }
                        if (bX == false) fX = fX0;
                        if (bY == false) fY = fY0;
                        if (bZ == false) fZ = fZ0;
                    }
                    if (m_bIgnoreCheckInit_CalcInv == true) m_bIgnoreCheckInit_CalcInv = false;
                    for (int nCalc = 0; nCalc < nRepeat; nCalc++)
                    {
                        fRes = 1.0f;
                        nPos = nCnt - 1;
                        while (nPos - 1 >= 0)
                        {
                            nID = anMotorIDs[nPos - 1];
                            fAngle0 = GetData(nID);

                            CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXc, out fYc, out fZc);
                            CalcF(nFunctionNumber, nID, bLimitFunctionNumber, out fXp, out fYp, out fZp);

                            fP = (float)Math.Sqrt(
                                Math.Pow(fX - fXc, 2) +
                                Math.Pow(fY - fYc, 2) +
                                Math.Pow(fZ - fZc, 2)
                                );
                            fN = (float)Math.Sqrt(
                                (float)Math.Pow(fXc - fXp, 2) +
                                (float)Math.Pow(fYc - fYp, 2) +
                                (float)Math.Pow(fZc - fZp, 2)
                                );
                            fC = (float)Math.Sqrt(
                                (float)Math.Pow(fX - fXp, 2) +
                                (float)Math.Pow(fY - fYp, 2) +
                                (float)Math.Pow(fZ - fZp, 2)
                                );
                            //float fAngle = 180.0f - (float)Ojw.CMath.ACos((fP * fP + fN * fN - fC * fC) / (2.0f * fP * fN)) - fAngle0;

                            fAngle1 = fAngle0 + (float)Ojw.CMath.ACos((fC * fC + fN * fN - fP * fP) / (2.0f * fC * fN));
                            fAngle2 = fAngle0 - ((float)Ojw.CMath.ACos((fC * fC + fN * fN - fP * fP) / (2.0f * fC * fN)));
                            bool bNon1 = false;
                            bool bNon2 = false;
                            if (Single.IsNaN(fAngle1)) { fAngle1 = fAngle0; bNon1 = true; }
                            else
                            {
                                float fTmp = fAngle1 % 360;
                                if (fTmp > 180) fTmp -= 360.0f;
                                else if (fTmp < -180) fTmp += 360.0f;
                                fAngle1 = CalcLimit(nID, fTmp);
                            }
                            if (Single.IsNaN(fAngle2)) { fAngle2 = fAngle0; bNon2 = true; }
                            else
                            {
                                float fTmp = fAngle2 % 360;
                                if (fTmp > 180) fTmp -= 360.0f;
                                else if (fTmp < -180) fTmp += 360.0f;
                                fAngle2 = CalcLimit(nID, fTmp);
                            }
                            //if ((bNon1 == true) && (bNon2 == true))
                            //{
                            //    nPos--;
                            //    continue;
                            //}
                            
#if true
#if true
                            if (bNon1 == false)
                            {
                                // Distance 계산
                                SetData(nID, fAngle1);
                                CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXc, out fYc, out fZc);
                                fC = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXc, 2) +
                                    (float)Math.Pow(fY - fYc, 2) +
                                    (float)Math.Pow(fZ - fZc, 2)
                                    );
                            }
                            else fC = 99999999f;

                            if (bNon2 == false)
                            {
                                SetData(nID, fAngle2);
                                CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXp, out fYp, out fZp);
                                fP = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXp, 2) +
                                    (float)Math.Pow(fY - fYp, 2) +
                                    (float)Math.Pow(fZ - fZp, 2)
                                    );
                            }
                            else fP = 99999999f;

                            
                            //float fVal1 = Math.Abs(fAngle0 - fAngle1);
                            //float fVal2 = Math.Abs(fAngle0 - fAngle2);
                            //if (fVal1 > fVal2)
                            //{
                            //    fAngle = 
                            //}
                            
                            
                            
                            //if ((fAngle1 < 0) && (fAngle2 > 0))
                            //{
                            //    if (fAngle0 > 0) fAngle = fAngle2;
                            //    else fAngle = fAngle1;
                            //}
                            //else if ((fAngle2 < 0) && (fAngle1 > 0))
                            //{
                            //    if (fAngle0 > 0) fAngle = fAngle1;
                            //    else fAngle = fAngle2;
                            //}
                            //else
                            //{
                                //float fVal1 = Math.Abs(fAngle0 - fAngle1);
                                //float fVal2 = Math.Abs(fAngle0 - fAngle2);
                                fAngle = CalcLimit(nID, (fP < fC) ? fAngle2 : fAngle1);
                                //fAngle = CalcLimit(nID, (fVal1 < fVal2) ? fAngle1 : fAngle2);
                            //}

#else
                            if ((IsLimit(nID, fAngle1) == false) && (IsLimit(nID, fAngle2) == false))
                            {
                                // Distance 계산
                                SetData(nID, fAngle1);
                                CalcF(nFunctionNumber, -1, out fXc, out fYc, out fZc);
                                fC = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXc, 2) +
                                    (float)Math.Pow(fY - fYc, 2) +
                                    (float)Math.Pow(fZ - fZc, 2)
                                    );

                                SetData(nID, fAngle2);
                                CalcF(nFunctionNumber, -1, out fXp, out fYp, out fZp);
                                fP = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXp, 2) +
                                    (float)Math.Pow(fY - fYp, 2) +
                                    (float)Math.Pow(fZ - fZp, 2)
                                    );
                                fAngle = (fC < fP) ? fAngle1 : fAngle2;
                            }
                            else if (IsLimit(nID, fAngle1) == false)
                            {
                                SetData(nID, fAngle1);
                                CalcF(nFunctionNumber, -1, out fXc, out fYc, out fZc);
                                fAngle = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXc, 2) +
                                    (float)Math.Pow(fY - fYc, 2) +
                                    (float)Math.Pow(fZ - fZc, 2)
                                    );
                            }
                            else// if (IsLimit(nID, fAngle2) == false)
                            {
                                SetData(nID, fAngle2);
                                CalcF(nFunctionNumber, -1, out fXp, out fYp, out fZp);
                                fAngle = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXp, 2) +
                                    (float)Math.Pow(fY - fYp, 2) +
                                    (float)Math.Pow(fZ - fZp, 2)
                                    );
                            }
                            //fAngle1 = CalcLimit(nID, fAngle1);
                            //fAngle2 = CalcLimit(nID, fAngle2);
#endif
                            


                            
#else

                            if (Math.Abs(fAngle0 - fAngle1) < Math.Abs(fAngle0 - fAngle2))
                                fAngle = fAngle1;
                            else fAngle = fAngle2;
#endif
                            SetData(nID, fAngle);

                            // lstAngles 갱신 (다음 iter 비교용)
                            for (int i = 0; i < nCnt; i++)
                                lstAngles[i] = GetData(anMotorIDs[i]);
                            nPos--;

                            // motor 별 endpoint 검사: 사용자 입력 tolerance 도달 즉시 종료
                            // (DC-CCD 는 한 iter 안에 큰 진전을 만들기 때문에 motor 별 검사가 효율적)
                            {
                                float fXm, fYm, fZm;
                                CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXm, out fYm, out fZm);
                                fRes = (float)Math.Sqrt((fX - fXm) * (fX - fXm) + (fY - fYm) * (fY - fYm) + (fZ - fZm) * (fZ - fZm));
                                if (fRes < fCutline) break; // inner while → outer for 의 검사로 fall-through
                            }
                        }

                        // 외부 for 검사: motor 별 검사가 잡았거나 iter 끝
                        if (fRes < fCutline) { m_nLastCalcInv_Iter = nCalc + 1; break; }
                        m_nLastCalcInv_Iter = nCalc + 1; // 매 iter 갱신 → 수렴 못 하면 최종 nRepeat
                    }
                    //CalcF(nFunctionNumber, -1, false, out fX0, out fY0, out fZ0);
                    //lstAngles.AddRange(CalcInv_LastOf(true, nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline));

                    // DC-CCD 는 단일 단계 (Phase 1 만). 이전에 있던 CalcInv2 (Phase 2) 호출은 제거
                    // — Phase 1 의 tie-break 가 시작 자세를 유지하므로 추가 sign-preserving 단계 불필요

                    return lstAngles.ToArray();
                }


                public float[] CalcInv2(int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    return CalcInv2(nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX, fY, fZ, null, nRepeat, fCutline);
                }
                public float[] CalcInv2(int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, double [] adV = null, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nID;
                    int nCnt = anMotorIDs.Length;
                    int nPos = nCnt;
                    float fX0 = fX, fY0 = fY, fZ0 = fZ;
                    float fXc = 0, fYc = 0, fZc = 0;
                    float fXp = 0, fYp = 0, fZp = 0;
                    float fX_Start, fY_Start, fZ_Start;
                    float fX_End, fY_End, fZ_End;
                    float fAngle0 = 0;
                    float fP = 0, fN = 0, fC = 0;
                    float fAngle, fAngle1, fAngle2;
                    List<float> lstAngles = new List<float>();
                    for (int i = 0; i < nCnt; i++)
                        lstAngles.Add(GetData(anMotorIDs[i]));
                    float fRes = 0.0f;

                    // DC-CCD tie-break 용: IK 호출 직전 자세 (iter 도중 갱신 안 됨)
                    float[] afStartAngles = new float[nCnt];
                    for (int i = 0; i < nCnt; i++) afStartAngles[i] = GetData(anMotorIDs[i]);

                    // End Point 획득
                    //CalcF(nFunctionNumber, -1, false, out fX_End, out fY_End, out fZ_End);

                    for (int nCalc = 0; nCalc < nRepeat; nCalc++)
                    {
                        fRes = 1.0f;
                        // last motor exclusion: motorIDs[nCnt-1] 은 dummy(255) 또는
                        //   사용자가 명시적으로 제외한 마지막 실 모터.
                        //   DH 끝 dummy 의 존재 여부가 "마지막 실 모터 포함/제외" 토글로 작동.
                        //   (다른 7 개 IK 함수와 일관 — WangChen / Kenwright / Probe / TracIK /
                        //    Ojha / OjwCCD_Variant / OjwCCD_V3_WithEpsTie 모두 동일)
                        nPos = nCnt - 1;
                        while (nPos - 1 >= 0)
                        {
                            nID = anMotorIDs[nPos - 1];
                            fAngle0 = GetData(nID);

                            CalcF(nFunctionNumber, -1, false, out fXc, out fYc, out fZc);
                            //fXc = fX; fYc = fY; fZc = fZ;
                            CalcF(nFunctionNumber, nID, false, out fXp, out fYp, out fZp);

                            CalcF(nFunctionNumber, nID, true, out fX_Start, out fY_Start, out fZ_Start);
                            if (Ojw.CKinematics.CForward.CheckCalc() != 2) break;
 
                            fP = (float)Math.Sqrt(
                                Math.Pow(fX - fXc, 2) +
                                Math.Pow(fY - fYc, 2) +
                                Math.Pow(fZ - fZc, 2)
                                );
                            fN = (float)Math.Sqrt(
                                (float)Math.Pow(fXc - fXp, 2) +
                                (float)Math.Pow(fYc - fYp, 2) +
                                (float)Math.Pow(fZc - fZp, 2)
                                );
                            fC = (float)Math.Sqrt(
                                (float)Math.Pow(fX - fXp, 2) +
                                (float)Math.Pow(fY - fYp, 2) +
                                (float)Math.Pow(fZ - fZp, 2)
                                );
                            //float fAngle = 180.0f - (float)Ojw.CMath.ACos((fP * fP + fN * fN - fC * fC) / (2.0f * fP * fN)) - fAngle0;

                            fAngle1 = fAngle0 + (float)Ojw.CMath.ACos((fC * fC + fN * fN - fP * fP) / (2.0f * fC * fN));
                            fAngle2 = fAngle0 - ((float)Ojw.CMath.ACos((fC * fC + fN * fN - fP * fP) / (2.0f * fC * fN)));
                            bool bNon1 = false;
                            bool bNon2 = false;
                            if (Single.IsNaN(fAngle1)) { fAngle1 = fAngle0; bNon1 = true; }
                            if (Single.IsNaN(fAngle2)) { fAngle2 = fAngle0; bNon2 = true; }

                            fAngle1 = CalcLimit(nID, fAngle1);
                            fAngle2 = CalcLimit(nID, fAngle2);

                            if (bNon1 == false)
                            {
                                // Distance 계산
                                SetData(nID, fAngle1);
                                CalcF(nFunctionNumber, -1, false, out fXc, out fYc, out fZc);
                                fC = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXc, 2) +
                                    (float)Math.Pow(fY - fYc, 2) +
                                    (float)Math.Pow(fZ - fZc, 2)
                                    );
                            }
                            else fC = 99999999f;

                            if (bNon2 == false)
                            {
                                SetData(nID, fAngle2);
                                CalcF(nFunctionNumber, -1, false, out fXp, out fYp, out fZp);
                                fP = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXp, 2) +
                                    (float)Math.Pow(fY - fYp, 2) +
                                    (float)Math.Pow(fZ - fZp, 2)
                                    );
                            }
                            else fP = 99999999f;


                            // DC-CCD 선택 규칙 (식 42):
                            //   1차: 거리 작은 쪽 (argmin(d+, d-))
                            //   2차(tie): |d+ - d-|/max(d+,d-,1) < eps_tie 이면
                            //            두 후보 중 IK 호출 직전 자세 (afStartAngles) 와
                            //            더 가까운 후보 선택 (각도 wrap-around 고려)
                            {
                                float fDelta_CP = Math.Abs(fC - fP);
                                float fScale_CP = Math.Max(Math.Max(fC, fP), 1.0f);
                                if (fDelta_CP / fScale_CP < 1e-6f)
                                {
                                    float fStart = afStartAngles[nPos - 1];
                                    float diff1 = (fAngle1 - fStart) % 360f;
                                    if (diff1 > 180f) diff1 -= 360f; else if (diff1 < -180f) diff1 += 360f;
                                    float diff2 = (fAngle2 - fStart) % 360f;
                                    if (diff2 > 180f) diff2 -= 360f; else if (diff2 < -180f) diff2 += 360f;
                                    float dS1 = Math.Abs(diff1), dS2 = Math.Abs(diff2);
                                    fAngle = CalcLimit(nID, (dS1 <= dS2) ? fAngle1 : fAngle2);
                                }
                                else
                                    fAngle = CalcLimit(nID, (fC < fP) ? fAngle1 : fAngle2);
                            }

                            SetData(nID, fAngle);

                            // lstAngles 갱신 (다음 iter 비교용)
                            for (int i = 0; i < nCnt; i++)
                                lstAngles[i] = GetData(anMotorIDs[i]);
                            nPos--;
                        }

                        // 수렴 종료: endpoint 거리(mm) 기반 — fCutline 이 mm 단위 직관과 일치
                        {
                            float fXe, fYe, fZe;
                            CalcF(nFunctionNumber, -1, false, out fXe, out fYe, out fZe);
                            fRes = (float)Math.Sqrt((fX - fXe) * (fX - fXe) + (fY - fYe) * (fY - fYe) + (fZ - fZe) * (fZ - fZe));
                            if (fRes < fCutline)
                            {
                                if (fC < fP)
                                {
                                    fX_End = fXc;
                                    fY_End = fYc;
                                    fZ_End = fZc;
                                }
                                else
                                {
                                    fX_End = fXp;
                                    fY_End = fYp;
                                    fZ_End = fZp;
                                }
                                m_nLastCalcInv2_Iter = nCalc + 1;
                                break;
                            }
                        }
                        m_nLastCalcInv2_Iter = nCalc + 1; // 매 iter 갱신 → 수렴 못 하면 최종 nRepeat
                    }
                    //CalcF(nFunctionNumber, -1, false, out fX0, out fY0, out fZ0);
                    //lstAngles.AddRange(CalcInv_LastOf(true, nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline));



                    // 2차 함수 계산 ////////////////////////////////////////
                    int[] anMotorID = new int[256];
                    double[] adValue = new double[256];
                    int nGetCnt_Lines = m_CHeader.pDhParamAll[nFunctionNumber].GetCount();
                    // int[] anFunctions = m_CHeader.pDhParamAll[nFunctionNumber].GetFunctions();// GetHeader_pDhParamAll()[nFunctionNumber].GetFunctions_AfterCalc(); // m_CHeader.pDhParamAll[nFunctionNumber].GetFunctions_AfterCalc();
                    if (nGetCnt_Lines > 0) // CDhParam 데이터의 갯수가 있을 경우
                    {
                        //double[] adV = Ojw.CKinematics.CInverse.GetValue_V();
                        for (int nT = nGetCnt_Lines - 1; nT >= 0; nT--) // 마지막 데이터만...
                        {
                            int nFunction_AfterCalc = m_CHeader.pDhParamAll[nFunctionNumber].GetData(nT).nFunctionNumber_AfterCalc;
                            if ((nFunction_AfterCalc >= 0) && (nFunction_AfterCalc < 255))
                            {
                                int nCntT = GetData_Inverse(nFunction_AfterCalc, fX, fY, fZ, adV, out anMotorID, out adValue);
                                for (int i = 0; i < nCntT; i++)
                                {
                                    SetData(anMotorID[i], (float)adValue[i]);
                                }
                                break;
                            }
                        }
                    }
                    // 2차 함수 계산 ////////////////////////////////////////

                    return lstAngles.ToArray();
                }

                // ============================================================
                // CalcInv_FABRIK - FABRIK (Forward And Backward Reaching IK)
                // CCD와 동일한 인터페이스, m_nCalcInv_IKAlgorithm == 1 일 때 호출됨
                //
                // FABRIK 알고리즘:
                //   1) FK로 모든 관절 위치 수집
                //   2) Backward pass: 엔드이펙터를 목표로 이동, 체인을 역방향으로 당김
                //   3) Forward pass: 베이스를 고정, 체인을 순방향으로 밀어냄
                //   4) 각도 복원: FABRIK 목표 위치에 맞게 각 관절 각도를 코사인 법칙으로 조정
                // ============================================================
                public float[] CalcInv_FABRIK(int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    m_nLastCalcInv_FABRIK_Iter = 0;
                    int nID;
                    int nCnt = anMotorIDs.Length;
                    int nJoints = nCnt + 1; // 관절 수 + 엔드이펙터

                    List<float> lstAngles = new List<float>();
                    for (int i = 0; i < nCnt; i++)
                        lstAngles.Add(GetData(anMotorIDs[i]));
                    float fRes = 0.0f;

                    float fX0 = fX, fY0 = fY, fZ0 = fZ;
                    float fXc, fYc, fZc;
                    float fXp, fYp, fZp;
                    float fX1, fY1, fZ1;
                    float fX2, fY2, fZ2;

                    CalcF(nFunctionNumber, -1, true, out fX1, out fY1, out fZ1);

                    // 방향 제한 확인 (CCD와 동일)
                    if (m_bIgnoreCheckInit_CalcInv == false)
                    {
                        CalcF(nFunctionNumber, -1, false, out fX0, out fY0, out fZ0);
                        bool bX = false, bY = false, bZ = false;
                        for (int i = 0; i < anMotorIDs.Length; i++)
                        {
                            if (bX && bY && bZ) break;
                            float fVal = GetData(anMotorIDs[i]);
                            SetData(anMotorIDs[i], fVal + 10);
                            CalcF(nFunctionNumber, -1, false, out fXp, out fYp, out fZp);
                            if (!bX && fX0 != fXp) bX = true;
                            if (!bY && fY0 != fYp) bY = true;
                            if (!bZ && fZ0 != fZp) bZ = true;
                            SetData(anMotorIDs[i], fVal - 10);
                            CalcF(nFunctionNumber, -1, false, out fXp, out fYp, out fZp);
                            if (!bX && fX0 != fXp) bX = true;
                            if (!bY && fY0 != fYp) bY = true;
                            if (!bZ && fZ0 != fZp) bZ = true;
                            SetData(anMotorIDs[i], fVal);
                        }
                        if (!bX) fX = fX0;
                        if (!bY) fY = fY0;
                        if (!bZ) fZ = fZ0;
                    }
                    if (m_bIgnoreCheckInit_CalcInv == true) m_bIgnoreCheckInit_CalcInv = false;

                    // FABRIK 위치 배열
                    float[] jx = new float[nJoints];
                    float[] jy = new float[nJoints];
                    float[] jz = new float[nJoints];
                    float[] fabX = new float[nJoints];
                    float[] fabY = new float[nJoints];
                    float[] fabZ = new float[nJoints];
                    float[] linkLen = new float[nCnt];

                    for (int nCalc = 0; nCalc < nRepeat; nCalc++)
                    {
                        fRes = 1.0f;

                        // (1) FK로 현재 관절 위치 수집
                        for (int i = 0; i < nCnt; i++)
                            CalcF(nFunctionNumber, anMotorIDs[i], bLimitFunctionNumber, out jx[i], out jy[i], out jz[i]);
                        CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out jx[nCnt], out jy[nCnt], out jz[nCnt]);

                        // 링크 길이 계산
                        for (int i = 0; i < nCnt; i++)
                        {
                            float dx = jx[i + 1] - jx[i], dy = jy[i + 1] - jy[i], dz = jz[i + 1] - jz[i];
                            linkLen[i] = (float)Math.Sqrt(dx * dx + dy * dy + dz * dz);
                        }

                        // FABRIK 배열 초기화
                        Array.Copy(jx, fabX, nJoints);
                        Array.Copy(jy, fabY, nJoints);
                        Array.Copy(jz, fabZ, nJoints);

                        // (2) FABRIK Backward pass: 엔드이펙터 → 베이스
                        fabX[nCnt] = fX; fabY[nCnt] = fY; fabZ[nCnt] = fZ;
                        for (int i = nCnt - 1; i >= 0; i--)
                        {
                            float dx = fabX[i] - fabX[i + 1];
                            float dy = fabY[i] - fabY[i + 1];
                            float dz = fabZ[i] - fabZ[i + 1];
                            float d = (float)Math.Sqrt(dx * dx + dy * dy + dz * dz);
                            if (d < 1e-6f) continue;
                            float r = linkLen[i] / d;
                            fabX[i] = fabX[i + 1] + r * dx;
                            fabY[i] = fabY[i + 1] + r * dy;
                            fabZ[i] = fabZ[i + 1] + r * dz;
                        }

                        // (3) FABRIK Forward pass: 베이스 → 엔드이펙터 (베이스 고정)
                        fabX[0] = jx[0]; fabY[0] = jy[0]; fabZ[0] = jz[0];
                        for (int i = 0; i < nCnt; i++)
                        {
                            float dx = fabX[i + 1] - fabX[i];
                            float dy = fabY[i + 1] - fabY[i];
                            float dz = fabZ[i + 1] - fabZ[i];
                            float d = (float)Math.Sqrt(dx * dx + dy * dy + dz * dz);
                            if (d < 1e-6f) continue;
                            float r = linkLen[i] / d;
                            fabX[i + 1] = fabX[i] + r * dx;
                            fabY[i + 1] = fabY[i] + r * dy;
                            fabZ[i + 1] = fabZ[i] + r * dz;
                        }

                        // (4) 각도 복원: Gradient Descent (base→end, 마지막 모터 제외)
                        // 코사인법칙의 ±2후보 대신 gradient로 유일한 방향을 구해 flipping 방지
                        // child 가 회전축 위에 있어 probe 시 안 움직이는 motor 는 다음 child 로 fallback
                        for (int j = 0; j < nCnt - 1; j++)
                        {
                            nID = anMotorIDs[j];
                            float fAngle0 = GetData(nID);
                            float fProbe = 1.0f;

                            // ----- useIdx 결정: probe 시 충분히 움직이는 첫 자식 -----
                            int useIdx = j + 1;
                            float fXc_u = 0, fYc_u = 0, fZc_u = 0;
                            float fXp_u = 0, fYp_u = 0, fZp_u = 0;
                            bool bUsable = false;
                            for (int probeIdx = j + 1; probeIdx <= nCnt; probeIdx++)
                            {
                                if (probeIdx < nCnt)
                                    CalcF(nFunctionNumber, anMotorIDs[probeIdx], bLimitFunctionNumber, out fXc_u, out fYc_u, out fZc_u);
                                else
                                    CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXc_u, out fYc_u, out fZc_u);

                                SetData(nID, fAngle0 + fProbe);
                                if (probeIdx < nCnt)
                                    CalcF(nFunctionNumber, anMotorIDs[probeIdx], bLimitFunctionNumber, out fXp_u, out fYp_u, out fZp_u);
                                else
                                    CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXp_u, out fYp_u, out fZp_u);
                                SetData(nID, fAngle0);

                                float dxc = fXp_u - fXc_u, dyc = fYp_u - fYc_u, dzc = fZp_u - fZc_u;
                                float dC = (float)Math.Sqrt(dxc * dxc + dyc * dyc + dzc * dzc);
                                if (dC > 1e-3f)
                                {
                                    useIdx = probeIdx;
                                    bUsable = true;
                                    break;
                                }
                            }
                            if (!bUsable) continue; // 이 motor 가 어떤 후속 위치에도 영향 못 줌

                            // FABRIK 목표 위치 (useIdx)
                            float ftx = (useIdx <= nCnt - 1) ? fabX[useIdx] : fabX[nCnt];
                            float fty = (useIdx <= nCnt - 1) ? fabY[useIdx] : fabY[nCnt];
                            float ftz = (useIdx <= nCnt - 1) ? fabZ[useIdx] : fabZ[nCnt];

                            // 현재 거리² (d_current)
                            fXc = fXc_u; fYc = fYc_u; fZc = fZc_u;
                            float dCurrent = (float)(Math.Pow(ftx - fXc, 2) + Math.Pow(fty - fYc, 2) + Math.Pow(ftz - fZc, 2));

                            // +probe 방향 거리² (이미 위에서 측정한 값 사용)
                            fXp = fXp_u; fYp = fYp_u; fZp = fZp_u;
                            float dPlus = (float)(Math.Pow(ftx - fXp, 2) + Math.Pow(fty - fYp, 2) + Math.Pow(ftz - fZp, 2));

                            // -probe 방향 거리²
                            SetData(nID, fAngle0 - fProbe);
                            if (useIdx < nCnt)
                                CalcF(nFunctionNumber, anMotorIDs[useIdx], bLimitFunctionNumber, out fXp, out fYp, out fZp);
                            else
                                CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXp, out fYp, out fZp);
                            SetData(nID, fAngle0);
                            float dMinus = (float)(Math.Pow(ftx - fXp, 2) + Math.Pow(fty - fYp, 2) + Math.Pow(ftz - fZp, 2));

                            // Gradient (1차 미분) & Hessian (2차 미분)
                            float gradient = (dPlus - dMinus) / (2.0f * fProbe);
                            float hessian = (dPlus + dMinus - 2.0f * dCurrent) / (fProbe * fProbe);

                            // Newton step: -gradient/hessian (2차 근사의 최적점)
                            float fStep;
                            if (hessian > 1e-6f)
                                fStep = -gradient / hessian;
                            else if (Math.Abs(gradient) > 1e-6f)
                                fStep = -Math.Sign(gradient) * 5.0f;
                            else
                                fStep = 0;

                            // 스텝 제한 (과도한 점프 방지)
                            float fMaxStep = 30.0f;
                            if (fStep > fMaxStep) fStep = fMaxStep;
                            else if (fStep < -fMaxStep) fStep = -fMaxStep;

                            float fAngle = CalcLimit(nID, fAngle0 + fStep);
                            SetData(nID, fAngle);

                            // FABRIK 타겟 업데이트: 실제 FK 위치 기반으로 forward pass 재실행
                            {
                                float fXact, fYact, fZact;
                                CalcF(nFunctionNumber, anMotorIDs[j + 1], bLimitFunctionNumber, out fXact, out fYact, out fZact);
                                fabX[j + 1] = fXact;
                                fabY[j + 1] = fYact;
                                fabZ[j + 1] = fZact;
                                for (int k = j + 1; k < nCnt; k++)
                                {
                                    float dxk = fabX[k + 1] - fabX[k];
                                    float dyk = fabY[k + 1] - fabY[k];
                                    float dzk = fabZ[k + 1] - fabZ[k];
                                    float dk = (float)Math.Sqrt(dxk * dxk + dyk * dyk + dzk * dzk);
                                    if (dk < 1e-6f) continue;
                                    float rk = linkLen[k] / dk;
                                    fabX[k + 1] = fabX[k] + rk * dxk;
                                    fabY[k + 1] = fabY[k] + rk * dyk;
                                    fabZ[k + 1] = fabZ[k] + rk * dzk;
                                }
                            }
                        }

                        // lstAngles 갱신
                        for (int i = 0; i < nCnt; i++)
                            lstAngles[i] = GetData(anMotorIDs[i]);

                        // 수렴 종료: endpoint 거리(mm) 기반
                        {
                            float fXe, fYe, fZe;
                            CalcF(nFunctionNumber, -1, bLimitFunctionNumber, out fXe, out fYe, out fZe);
                            fRes = (float)Math.Sqrt((fX - fXe) * (fX - fXe) + (fY - fYe) * (fY - fYe) + (fZ - fZe) * (fZ - fZe));
                            if (fRes < fCutline) { m_nLastCalcInv_FABRIK_Iter = nCalc + 1; break; }
                        }
                        m_nLastCalcInv_FABRIK_Iter = nCalc + 1;
                    }

                    // CalcInv_Mode 처리 (CCD와 동일)
                    if ((m_nCalcInv_Mode == 2) || (m_nCalcInv_Mode == 0))
                    {
                        lstAngles.Clear();
                        CalcF(nFunctionNumber, -1, true, out fX2, out fY2, out fZ2);
                        double[] adV = (double[])Ojw.CKinematics.CInverse.GetValue_V().Clone();
                        lstAngles.AddRange(CalcInv2(nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX0, fY0, fZ0, adV, nRepeat, fCutline));
                    }

                    return lstAngles.ToArray();
                }

                // ============================================================
                // IK Algorithm Wrappers
                // 알고리즘별 명시적 호출을 위한 래퍼 함수들
                // ============================================================

                // OjwCCDIK - OpenJigWare 독자 CCD-IK 알고리즘
                public float[] OjwCCDIK(int nFunctionNumber, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nPrev = m_nCalcInv_IKAlgorithm;
                    m_nCalcInv_IKAlgorithm = 0;
                    float[] result = CalcInv(nFunctionNumber, fX, fY, fZ, nRepeat, fCutline);
                    m_nCalcInv_IKAlgorithm = nPrev;
                    return result;
                }
                public float[] OjwCCDIK(int nFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nPrev = m_nCalcInv_IKAlgorithm;
                    m_nCalcInv_IKAlgorithm = 0;
                    float[] result = CalcInv(nFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline);
                    m_nCalcInv_IKAlgorithm = nPrev;
                    return result;
                }
                public float[] OjwCCDIK(int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nPrev = m_nCalcInv_IKAlgorithm;
                    m_nCalcInv_IKAlgorithm = 0;
                    float[] result = CalcInv(nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline);
                    m_nCalcInv_IKAlgorithm = nPrev;
                    return result;
                }

                // OjwFABRIK - FABRIK 알고리즘 래퍼
                public float[] OjwFABRIK(int nFunctionNumber, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nPrev = m_nCalcInv_IKAlgorithm;
                    m_nCalcInv_IKAlgorithm = 1;
                    float[] result = CalcInv(nFunctionNumber, fX, fY, fZ, nRepeat, fCutline);
                    m_nCalcInv_IKAlgorithm = nPrev;
                    return result;
                }
                public float[] OjwFABRIK(int nFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nPrev = m_nCalcInv_IKAlgorithm;
                    m_nCalcInv_IKAlgorithm = 1;
                    float[] result = CalcInv(nFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline);
                    m_nCalcInv_IKAlgorithm = nPrev;
                    return result;
                }
                public float[] OjwFABRIK(int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nPrev = m_nCalcInv_IKAlgorithm;
                    m_nCalcInv_IKAlgorithm = 1;
                    float[] result = CalcInv(nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline);
                    m_nCalcInv_IKAlgorithm = nPrev;
                    return result;
                }

                // OjwJacobianIK - Jacobian DLS (Damped Least Squares) 래퍼
                public bool OjwJacobianIK(int nFunctionNumber, float fX, float fY, float fZ,
                    int maxIter = 1000, float tolMm = 0.001f, float epsDeg = 0.01f,
                    float lambda = 0.5f, float gain = 1.0f, float maxStepDeg = 5.0f)
                {
                    Ojw.C3d c3d = this;
                    return Ojw.CKinematics.CInverse.SolveIK_JacobianDLS_PosOnly(
                        ref c3d, nFunctionNumber, fX, fY, fZ,
                        maxIter, tolMm, epsDeg, lambda, gain, maxStepDeg);
                }
                public bool OjwJacobianIK(int nFunctionNumber, float fX, float fY, float fZ,
                    float rxDeg, float ryDeg, float rzDeg, float toolLength,
                    int maxIter = 1000, float tolMm = 0.001f, float epsDeg = 0.01f,
                    float lambda = 0.5f, float gain = 1.0f, float maxStepDeg = 5.0f)
                {
                    Ojw.C3d c3d = this;
                    return Ojw.CKinematics.CInverse.SolveIK_JacobianDLS_PosWithTool(
                        ref c3d, nFunctionNumber, fX, fY, fZ,
                        rxDeg, ryDeg, rzDeg, toolLength,
                        maxIter, tolMm, epsDeg, lambda, gain, maxStepDeg);
                }
                public bool OjwJacobianIK_Global(int nFunctionNumber, float fX, float fY, float fZ,
                    float rxDeg, float ryDeg, float rzDeg, float toolLength,
                    int maxIter = 1000, float tolMm = 0.001f, float epsDeg = 0.01f,
                    float lambda = 0.5f, float gain = 1.0f, float maxStepDeg = 5.0f)
                {
                    Ojw.C3d c3d = this;
                    return Ojw.CKinematics.CInverse.SolveIK_JacobianDLS_PosWithToolGlobal(
                        ref c3d, nFunctionNumber, fX, fY, fZ,
                        rxDeg, ryDeg, rzDeg, toolLength,
                        maxIter, tolMm, epsDeg, lambda, gain, maxStepDeg);
                }

                // ================================================================
                // 수직 툴 IK (손목 분리) + 시간 기반 관절 모션 (2026-08-21)
                // ----------------------------------------------------------------
                // · CalcInv_VerticalTool : 손목 분리(kinematic decoupling) 역기구학.
                //     ① 툴이 수직(아래)이면 손목축 원점은 TCP 바로 위(손목-TCP 강체 길이)
                //        → 위치 담당 관절 3개만 DLS 로 손목 위치를 맞춘다 (FK = CalcF)
                //     ② 손목각은 반복 없이 FK 에서 툴 피치를 실측해 부족분을 직접 보정
                //        (기울기 ∂피치/∂손목각도 ±10도 실측 — 부호 가정 없음)
                //     ③ TCP 잔차만큼 손목 목표를 밀어 재시도 (강체 미세 오프셋 흡수)
                // · MoveJoints_* / MoveTool_* : smoothstep 시간 보간 모션.
                //     Step() 을 렌더 틱(OjwDraw 직전)에서 부르면 관절 갱신과 그리기가
                //     같은 순간에 일어나 떨림(스레드 엇박·부분 갱신)이 없다.
                //     MoveTool_Start 의 IK 도 Step() 첫 호출에서 풀리므로 (렌더 스레드)
                //     다른 스레드의 FK 와 상태가 충돌하지 않는다.
                // ================================================================
                #region VerticalTool IK + MoveJoints

                private static double Det3_VT(double[,] a)
                {
                    return a[0, 0] * (a[1, 1] * a[2, 2] - a[1, 2] * a[2, 1])
                         - a[0, 1] * (a[1, 0] * a[2, 2] - a[1, 2] * a[2, 0])
                         + a[0, 2] * (a[1, 0] * a[2, 1] - a[1, 1] * a[2, 0]);
                }

                /// <summary>현재 자세의 툴 피치(도) — 'TCP − 손목축 원점' 벡터 실측 (수평 0 / 수직 아래 +90)</summary>
                public float CalcToolPitch(int nFunctionNumber, int nWristID)
                {
                    float fTx, fTy, fTz, fWx, fWy, fWz;
                    CalcF(nFunctionNumber, -1, false, out fTx, out fTy, out fTz);
                    CalcF(nFunctionNumber, nWristID, false, out fWx, out fWy, out fWz);
                    double dVx = fTx - fWx, dVy = fTy - fWy, dVz = fTz - fWz;
                    return (float)(Math.Atan2(-dVz, Math.Sqrt(dVx * dVx + dVy * dVy)) * 180.0 / Math.PI);
                }

                /// <summary>위치 관절 3개 DLS — 손목축(nWristID) 원점을 (wx,wy,wz)로. FK 는 CalcF</summary>
                private bool SolveWrist_VT(int nFunc, int nWristID, int[] anPosIDs, double[] q,
                                           double dWx, double dWy, double dWz)
                {
                    const double dH = 0.5, dLam = 0.5;
                    double dBest = double.MaxValue;
                    int nNoImprove = 0;
                    for (int nIter = 0; nIter < 100; nIter++)
                    {
                        for (int i = 0; i < 3; i++) SetData(anPosIDs[i], (float)q[i]);
                        float fCx, fCy, fCz;
                        CalcF(nFunc, nWristID, false, out fCx, out fCy, out fCz);
                        double dEx = dWx - fCx, dEy = dWy - fCy, dEz = dWz - fCz;
                        double dErr2 = dEx * dEx + dEy * dEy + dEz * dEz;
                        if (dErr2 < 0.04) return true;   // 0.2mm
                        // 정체 감지 — 도달 불가 목표는 개선이 플래토에 멈춘다.
                        // 조기 포기해야 실패 탐색이 싸져 렌더 틱이 얼어붙지 않는다(순간이동처럼 보이는 원인).
                        // 단, 리치 경계의 "느린 수렴"(댐핑으로 개선폭이 작지만 계속 줄어듦)은
                        // 상대 개선(2%)으로 구제한다 — 절대량만 보면 도달 가능 지점을 실패로 오판(실측)
                        if (dErr2 < dBest - 0.25 || dErr2 < dBest * 0.98) { dBest = dErr2; nNoImprove = 0; }
                        else if (++nNoImprove >= 25) return false;

                        double[,] adJ = new double[3, 3];
                        for (int j = 0; j < 3; j++)
                        {
                            q[j] += dH;
                            for (int i = 0; i < 3; i++) SetData(anPosIDs[i], (float)q[i]);
                            float fPx, fPy, fPz;
                            CalcF(nFunc, nWristID, false, out fPx, out fPy, out fPz);
                            q[j] -= dH;
                            adJ[0, j] = (fPx - fCx) / dH; adJ[1, j] = (fPy - fCy) / dH; adJ[2, j] = (fPz - fCz) / dH;
                        }
                        // (JᵀJ + λ²I) dq = Jᵀe — 3x3 크래머
                        double[,] adA = new double[3, 3];
                        double[] adB = new double[3];
                        double[] adE = { dEx, dEy, dEz };
                        for (int r = 0; r < 3; r++)
                        {
                            for (int c = 0; c < 3; c++)
                            { double dS = 0; for (int k = 0; k < 3; k++) dS += adJ[k, r] * adJ[k, c]; adA[r, c] = dS; }
                            adA[r, r] += dLam * dLam;
                            for (int k = 0; k < 3; k++) adB[r] += adJ[k, r] * adE[k];
                        }
                        double dDet = Det3_VT(adA);
                        if (Math.Abs(dDet) < 1e-12) return false;
                        for (int j = 0; j < 3; j++)
                        {
                            double[,] adAj = (double[,])adA.Clone();
                            for (int r = 0; r < 3; r++) adAj[r, j] = adB[r];
                            double dDq = Det3_VT(adAj) / dDet;
                            if (dDq > 20) dDq = 20; else if (dDq < -20) dDq = -20;
                            q[j] += dDq;
                        }
                    }
                    return false;
                }

                private float[] SolveTool_From(int nFunc, int nWristID, int[] anPosIDs, double[] qSeed,
                                               float fX, float fY, float fZ, double dPitchDeg, double dWristLen,
                                               double dTolMm)
                {
                    double[] q = (double[])qSeed.Clone();
                    double dQw = GetData(nWristID);
                    // 손목 목표 = TCP − (손목→TCP 방향) × 강체길이.
                    // 방향은 목표 피치와 요(위치에서 추정: atan2(y,x))로 — 잔차 보정 루프가 오차를 흡수한다
                    double dPitchRad = dPitchDeg * Math.PI / 180.0;
                    double dYawRad = Math.Atan2(fY, fX);
                    double dDirX = Math.Cos(dPitchRad) * Math.Cos(dYawRad);
                    double dDirY = Math.Cos(dPitchRad) * Math.Sin(dYawRad);
                    double dDirZ = -Math.Sin(dPitchRad);
                    double dWx = fX - dDirX * dWristLen;
                    double dWy = fY - dDirY * dWristLen;
                    double dWz = fZ - dDirZ * dWristLen;
                    for (int nOuter = 0; nOuter < 6; nOuter++)
                    {
                        if (!SolveWrist_VT(nFunc, nWristID, anPosIDs, q, dWx, dWy, dWz)) break;

                        // 손목각 — FK 에서 피치를 실측해 직접 보정 (기울기도 실측)
                        SetData(nWristID, (float)dQw);
                        double dP0 = CalcToolPitch(nFunc, nWristID);
                        SetData(nWristID, (float)(dQw + 10.0));
                        double dSlope = (CalcToolPitch(nFunc, nWristID) - dP0) / 10.0;
                        if (Math.Abs(dSlope) < 0.2) break;   // 피치축이 아님
                        dQw += (dPitchDeg - dP0) / dSlope;
                        SetData(nWristID, (float)dQw);
                        dQw += (dPitchDeg - CalcToolPitch(nFunc, nWristID)) / dSlope;   // 2차 보정
                        SetData(nWristID, (float)dQw);

                        float fCx, fCy, fCz;
                        CalcF(nFunc, -1, false, out fCx, out fCy, out fCz);
                        double dEx = fX - fCx, dEy = fY - fCy, dEz = fZ - fCz;
                        if (Math.Sqrt(dEx * dEx + dEy * dEy + dEz * dEz) < dTolMm)
                            return new[] { (float)q[0], (float)q[1], (float)q[2], (float)dQw };
                        dWx += dEx; dWy += dEy; dWz += dEz;
                    }
                    return null;
                }

                /// <summary>손목 분리 툴 자세 역기구학 — 툴 피치를 fPitchDeg(90=수직 아래, 0=수평)로
                /// 유지한 채 TCP 를 (x,y,z)에. anPosMotorIDs = 위치 담당 관절 3개, nWristID = 손목 피치.
                /// 성공 시 [pos0, pos1, pos2, 손목] 각도, 실패(도달 불가) 시 null. 탐색 후 자세는 원복.</summary>
                public float[] CalcInv_Tool(int nFunctionNumber, float fX, float fY, float fZ,
                                            float fPitchDeg, int nWristID, int[] anPosMotorIDs)
                {
                    if (anPosMotorIDs == null || anPosMotorIDs.Length != 3) return null;

                    // 손목-TCP 강체 길이 실측 (자세 무관 상수)
                    float fTx, fTy, fTz, fWx, fWy, fWz;
                    CalcF(nFunctionNumber, -1, false, out fTx, out fTy, out fTz);
                    CalcF(nFunctionNumber, nWristID, false, out fWx, out fWy, out fWz);
                    double dWristLen = Math.Sqrt((fTx - fWx) * (fTx - fWx) + (fTy - fWy) * (fTy - fWy) + (fTz - fWz) * (fTz - fWz));

                    float[] afSave = { GetData(anPosMotorIDs[0]), GetData(anPosMotorIDs[1]),
                                       GetData(anPosMotorIDs[2]), GetData(nWristID) };
                    double[] qSeed1 = { afSave[0], afSave[1], afSave[2] };            // 현재 자세 (연속 해)
                    double[] qSeed2 = { afSave[0], -30.0, 60.0 };                     // 굽힘 시드 (재시도)
                    float[] afRes = SolveTool_From(nFunctionNumber, nWristID, anPosMotorIDs, qSeed1, fX, fY, fZ, fPitchDeg, dWristLen, 1.0);
                    if (afRes == null)
                        afRes = SolveTool_From(nFunctionNumber, nWristID, anPosMotorIDs, qSeed2, fX, fY, fZ, fPitchDeg, dWristLen, 1.0);

                    // 탐색이 흔든 자세 원복 — 실제 이동은 호출자(MoveJoints 등)가 담당
                    SetData(anPosMotorIDs[0], afSave[0]); SetData(anPosMotorIDs[1], afSave[1]);
                    SetData(anPosMotorIDs[2], afSave[2]); SetData(nWristID, afSave[3]);
                    return afRes;
                }

                /// <summary>수직 툴 역기구학 — CalcInv_Tool 의 피치 90도(수직 아래) 특수형</summary>
                public float[] CalcInv_VerticalTool(int nFunctionNumber, float fX, float fY, float fZ,
                                                    int nWristID, int[] anPosMotorIDs)
                {
                    return CalcInv_Tool(nFunctionNumber, fX, fY, fZ, 90f, nWristID, anPosMotorIDs);
                }

                /// <summary>연속성 우선형 — 현재 자세 시드만 사용 (굽힘 시드 없음).
                /// 굽힘 시드는 팔 구성이 반전된 해를 내놓아 큰 스윙(순간이동처럼 보임)을 만들 수 있다</summary>
                private float[] CalcInv_Tool_Continuous(int nFunctionNumber, float fX, float fY, float fZ,
                                                        float fPitchDeg, int nWristID, int[] anPosMotorIDs,
                                                        double dTolMm)
                {
                    if (anPosMotorIDs == null || anPosMotorIDs.Length != 3) return null;
                    float fTx, fTy, fTz, fWx, fWy, fWz;
                    CalcF(nFunctionNumber, -1, false, out fTx, out fTy, out fTz);
                    CalcF(nFunctionNumber, nWristID, false, out fWx, out fWy, out fWz);
                    double dWristLen = Math.Sqrt((fTx - fWx) * (fTx - fWx) + (fTy - fWy) * (fTy - fWy) + (fTz - fWz) * (fTz - fWz));
                    float[] afSave = { GetData(anPosMotorIDs[0]), GetData(anPosMotorIDs[1]),
                                       GetData(anPosMotorIDs[2]), GetData(nWristID) };
                    double[] qSeed = { afSave[0], afSave[1], afSave[2] };
                    float[] afRes = SolveTool_From(nFunctionNumber, nWristID, anPosMotorIDs, qSeed, fX, fY, fZ, fPitchDeg, dWristLen, dTolMm);
                    SetData(anPosMotorIDs[0], afSave[0]); SetData(anPosMotorIDs[1], afSave[1]);
                    SetData(anPosMotorIDs[2], afSave[2]); SetData(nWristID, afSave[3]);
                    return afRes;
                }

                // ── 시간 기반 관절 모션 (smoothstep) ──
                // 두 플래그는 워커(Play_Wait 폴링)와 렌더 틱(Step)이 함께 보므로 volatile —
                // IsMoving() = (IDs != null) || pending. 어느 한쪽이라도 켜져 있는 동안이
                // "모션 중"이며, pending→IDs 전환 시 둘 다 꺼진 순간이 생기면 안 된다
                private volatile int[] m_anMoveJointIDs = null;     // null = 모션 없음
                private float[] m_afMoveJointFrom = null, m_afMoveJointTo = null;
                private int m_nMoveJointStartTick = 0, m_nMoveJointTime_ms = 1;
                // 모션 시계 — Environment.TickCount 는 15.6ms 양자화라 틱당 진행량이 1:2 로 널뛰어(실물 스트리밍 속도 요동)
                // Stopwatch 기반 ms 를 쓴다. 이 영역의 StartTick/LastTick 은 전부 이 시계 기준(상대값만 쓰므로 원점 무관)
                private static readonly long s_lMotionClockBase = System.Diagnostics.Stopwatch.GetTimestamp();
                private static int MotionTick_ms() { return (int)((System.Diagnostics.Stopwatch.GetTimestamp() - s_lMotionClockBase) * 1000L / System.Diagnostics.Stopwatch.Frequency); }
                private volatile bool m_bMoveToolPending = false;   // IK 를 Step() 에서 풀도록 예약
                private int m_nMoveToolFunc = 0, m_nMoveToolWrist = 0, m_nMoveToolTime = 0;
                private int[] m_anMoveToolPosIDs = null;
                private float m_fMoveToolX = 0, m_fMoveToolY = 0, m_fMoveToolZ = 0;
                private float m_fMoveToolPitch = 90f;               // 툴 피치 목표 (90 = 수직 아래)

                /// <summary>모션 상태 세팅 공통부 — From/To/시간을 먼저, IDs(활성 표시)를 마지막에</summary>
                private void MoveJoints_Activate(int nTime_ms, int[] anMotorIDs, float[] afTargetDeg)
                {
                    var afFrom = new float[anMotorIDs.Length];
                    for (int i = 0; i < anMotorIDs.Length; i++) afFrom[i] = GetData(anMotorIDs[i]);
                    m_afMoveJointFrom = afFrom;
                    m_afMoveJointTo = (float[])afTargetDeg.Clone();
                    m_nMoveJointTime_ms = Math.Max(1, nTime_ms);
                    m_nMoveJointStartTick = MotionTick_ms();
                    m_anMoveJointIDs = (int[])anMotorIDs.Clone();   // 마지막에 세팅 = 활성화
                }

                /// <summary>관절 모션 시작 (즉시 복귀) — 진행은 MoveJoints_Step() 이 담당</summary>
                public bool MoveJoints_Start(int nTime_ms, int[] anMotorIDs, float[] afTargetDeg)
                {
                    if (anMotorIDs == null || afTargetDeg == null || anMotorIDs.Length != afTargetDeg.Length) return false;
                    m_bMoveToolPending = false;
                    m_bPathRun = false;
                    m_sbPathLog = new System.Text.StringBuilder("#JOINT n=" + anMotorIDs.Length + "\r\n");
                    MoveJoints_Activate(nTime_ms, anMotorIDs, afTargetDeg);
                    return true;
                }

                /// <summary>툴 자세 유지 TCP 이동 시작 — 툴 자세는 3축 각도(도)로 지정:
                /// fRx=롤, fRy=피치(90=수직 아래), fRz=요. 현 손목분리 구현은 피치(fRy)를 손목으로
                /// 실현하며, 요는 팔 구조상 위치에 종속, 롤은 롤 관절을 별도 Play 로 제어한다.
                /// IK 는 Step() 첫 호출(렌더 스레드)에서 풀리고, 자세 불가 시 위치 전용 CalcInv 폴백</summary>
                public bool MoveTool_Start(int nFunctionNumber, float fX, float fY, float fZ, int nTime_ms,
                                           float fRxDeg, float fRyDeg, float fRzDeg,
                                           int nWristID, int[] anPosMotorIDs)
                {
                    if (anPosMotorIDs == null || anPosMotorIDs.Length != 3) return false;
                    m_anMoveJointIDs = null;
                    m_bPathRun = false;
                    m_sbPathLog = new System.Text.StringBuilder(string.Format(
                        "#TOOL tgt=({0:F1},{1:F1},{2:F1}) pitch={3:F0}\r\n", fX, fY, fZ, fRyDeg));
                    m_nMoveToolFunc = nFunctionNumber;
                    m_nMoveToolWrist = nWristID;
                    m_anMoveToolPosIDs = (int[])anPosMotorIDs.Clone();
                    m_fMoveToolX = fX; m_fMoveToolY = fY; m_fMoveToolZ = fZ;
                    m_fMoveToolPitch = fRyDeg;
                    m_nMoveToolTime = nTime_ms;
                    m_bMoveToolPending = true;                      // 마지막에 세팅 = 활성화
                    return true;
                }

                /// <summary>수직 툴(피치 90도) 이동 시작 — 3축 자세 지정형의 특수형</summary>
                public bool MoveTool_Start(int nFunctionNumber, float fX, float fY, float fZ, int nTime_ms,
                                           int nWristID, int[] anPosMotorIDs)
                {
                    return MoveTool_Start(nFunctionNumber, fX, fY, fZ, nTime_ms, 0f, 90f, 0f, nWristID, anPosMotorIDs);
                }

                // ── 연속 경로 추종 (폴리라인) — 렌더 틱마다 경로 위 목표점을 전진시키며
                //    현재 자세 웜스타트로 IK 를 푼다. 세그먼트 정지·재가속이 없어
                //    펜 드로잉처럼 선형 연속 동작이 필요한 곳에 쓴다 ──
                private volatile bool m_bPathRun = false;           // 경로 모션 활성 (IsMoving 포함)
                private bool m_bPathStarted = false;                // Step 첫 호출에서 준비(TCP 프리펜드)
                private float[] m_afPathPtsIn = null;               // 입력 점 (x,y,z 반복)
                private float[] m_afPathPts = null;                 // 현재 TCP 프리펜드 후
                private double[] m_adPathCum = null;                // 누적 길이
                private double m_dPathLen = 0;
                private int m_nPathTime_ms = 1, m_nPathStartTick = 0, m_nPathFunc = 0, m_nPathWrist = 0;
                private int[] m_anPathPosIDs = null;
                private float m_fPathPitch = 90f;
                private float m_fPathPitchCur = 90f;                // 현재 적용 중인 피치 (경로 내 단조 완화)
                private int m_nPathLastTick = 0;                    // 직전 Step 시각 (실패 시 시간 정지용)
                private System.Text.StringBuilder m_sbPathLog = null;   // 진단 — 틱별 기록

                public bool MoveJoints_IsMoving() { return (m_anMoveJointIDs != null) || m_bMoveToolPending || m_bPathRun; }
                public void MoveJoints_Stop() { m_anMoveJointIDs = null; m_bMoveToolPending = false; m_bPathRun = false; }

                // ── 단독 실행 지원 + 실물 스트리밍 훅 ──
                private volatile bool m_bMoveExternalPump = false;   // true = 앱 렌더 틱이 Step 을 돌린다
                private Action<int> m_MotionSink = null;             // 모션 스텝마다 호출 (실물 스트리밍 등)

                /// <summary>외부(렌더 틱)에서 MoveJoints_Step 을 돌리는 앱이면 true 로 선언할 것.
                /// false(기본)면 Play/PlayXyz/PlayXyzPath 의 대기 루프가 스스로 Step 을 진행한다 —
                /// 3D 창 없는 파이썬 단독 실행에서도 같은 코드가 같은 시간에 같은 동작을 한다</summary>
                public void MoveJoints_SetExternalPump(bool bOn) { m_bMoveExternalPump = bOn; }

                /// <summary>모션 스텝마다 호출되는 싱크 — CScene_t 가 실물 스트리밍(SendPose)을 등록한다.
                /// 렌더 틱이 돌리든 자가 펌프가 돌리든 스텝이 곧 전송 시점이라 실물 동작이 동일하다</summary>
                public void MoveJoints_SetMotionSink(Action<int> cb) { m_MotionSink = cb; }

                /// <summary>모션 한 스텝 — 렌더 틱(OjwDraw 직전)에서 호출할 것.
                /// 시간 기반이라 프레임이 밀려도 지정 시간에 정확히 도착한다</summary>
                public void MoveJoints_Step()
                {
                    if (m_bMoveToolPending)
                    {
                        // ※ pending 은 모션 활성화(IDs 세팅)가 끝난 "뒤"에 내린다.
                        //   먼저 내리면 IK 를 푸는 동안 IsMoving() 이 false 가 되어 워커의
                        //   Play_Wait 가 조기 복귀 → 파이썬이 다음 명령을 미리 실행하며
                        //   모션이 서로 덮어써진다(홈 미복귀·허공 파지·움찔거림 — 실측 재현)
                        // 1차: 현재 자세 시드만으로 피치 완화 탐색 — 자세 연속 최우선
                        //      (굽힘 시드 해는 팔 구성이 반전될 수 있어 큰 스윙을 만든다)
                        float[] afSol = null;
                        string strSolveMode = "";
                        // ★처짐 보상 — 모델이 로드돼 있으면 목표를 (목표 − 예상 처짐) 으로 바꿔 IK 에 넣는다.
                        //   로드 안 됐으면 그대로(비용 0). 사용자 목표(m_fMoveToolX…)는 건드리지 않는다. (COjw_12_3D_SagComp.cs)
                        float fTgX = m_fMoveToolX, fTgY = m_fMoveToolY, fTgZ = m_fMoveToolZ;
                        SagComp_Apply(ref fTgX, ref fTgY, ref fTgZ);
                        for (float fRelax = 0; fRelax <= 30 && afSol == null; fRelax += 10)
                        {
                            afSol = CalcInv_Tool_Continuous(m_nMoveToolFunc, fTgX, fTgY, fTgZ,
                                                            m_fMoveToolPitch - fRelax, m_nMoveToolWrist, m_anMoveToolPosIDs, 1.0);
                            if (afSol != null) strSolveMode = "cont relax=" + fRelax;
                        }
                        // 2차: 그래도 안 되면 굽힘 시드 포함 재탐색
                        for (float fRelax = 0; fRelax <= 30 && afSol == null; fRelax += 10)
                        {
                            afSol = CalcInv_Tool(m_nMoveToolFunc, fTgX, fTgY, fTgZ,
                                                 m_fMoveToolPitch - fRelax, m_nMoveToolWrist, m_anMoveToolPosIDs);
                            if (afSol != null) strSolveMode = "bent relax=" + fRelax;
                        }
                        int[] anIds;
                        if (afSol != null)
                        {
                            anIds = new[] { m_anMoveToolPosIDs[0], m_anMoveToolPosIDs[1], m_anMoveToolPosIDs[2], m_nMoveToolWrist };
                        }
                        else
                        {
                            // 최후 폴백: 위치 전용 CCD (자세 비보장)
                            // ※ CalcInv 는 현재 자세를 직접 바꿔가며 푸는 "제자리 풀이"다 — 풀고 나서
                            //   자세를 원복해야 보간이 "현재→해"로 일어난다. 원복 없이는 로봇이 해
                            //   자세로 즉시 점프하고 보간은 목표→목표가 되어 순간이동처럼 보인다
                            //   (팔레타이징 obj3 를 놓고 위로 튀어오르던 현상의 원인 — FK 로그 실측)
                            anIds = CalcInv_MotorIDs(m_nMoveToolFunc);
                            float[] afBefore = null;
                            if (anIds != null)
                            {
                                afBefore = new float[anIds.Length];
                                for (int i = 0; i < anIds.Length; i++) afBefore[i] = GetData(anIds[i]);
                            }
                            afSol = CalcInv(m_nMoveToolFunc, fTgX, fTgY, fTgZ, 300, 0.5f);
                            if (afBefore != null)
                                for (int i = 0; i < anIds.Length; i++) SetData(anIds[i], afBefore[i]);
                            if (afSol == null || anIds == null) { m_bMoveToolPending = false; return; }   // 완전 실패 — 모션 없음
                            strSolveMode = "ccd";
                        }
                        if (m_sbPathLog != null)
                        {
                            m_sbPathLog.Append("#SOLVE " + strSolveMode + " sol=");
                            for (int i = 0; i < afSol.Length; i++) m_sbPathLog.AppendFormat("{0:F1} ", afSol[i]);
                            m_sbPathLog.Append("\r\n");
                        }
                        MoveJoints_Activate(m_nMoveToolTime, anIds, afSol);
                        m_bMoveToolPending = false;   // IDs 활성 후 — IsMoving 이 한 순간도 꺼지지 않는다
                    }
                    if (m_bPathRun)
                    {
                        if (!m_bPathStarted)
                        {
                            // 준비(렌더 스레드 = FK 안전): 현재 TCP 를 경로 맨 앞에 붙여
                            // 시작점까지도 연속으로 이어지게 하고, 누적 길이를 계산한다
                            float fTx, fTy, fTz;
                            CalcF(m_nPathFunc, -1, false, out fTx, out fTy, out fTz);
                            int nPts = m_afPathPtsIn.Length / 3 + 1;
                            m_afPathPts = new float[nPts * 3];
                            m_afPathPts[0] = fTx; m_afPathPts[1] = fTy; m_afPathPts[2] = fTz;
                            Array.Copy(m_afPathPtsIn, 0, m_afPathPts, 3, m_afPathPtsIn.Length);
                            m_adPathCum = new double[nPts];
                            m_dPathLen = 0;
                            for (int i = 1; i < nPts; i++)
                            {
                                double dDx = m_afPathPts[i * 3] - m_afPathPts[i * 3 - 3];
                                double dDy = m_afPathPts[i * 3 + 1] - m_afPathPts[i * 3 - 2];
                                double dDz = m_afPathPts[i * 3 + 2] - m_afPathPts[i * 3 - 1];
                                m_dPathLen += Math.Sqrt(dDx * dDx + dDy * dDy + dDz * dDz);
                                m_adPathCum[i] = m_dPathLen;
                            }
                            if (m_dPathLen < 1e-6) { m_bPathRun = false; return; }
                            m_nPathStartTick = MotionTick_ms();
                            m_nPathLastTick = m_nPathStartTick;
                            m_bPathStarted = true;
                        }
                        double dTp = (double)(MotionTick_ms() - m_nPathStartTick) / m_nPathTime_ms;
                        if (dTp >= 1.0) dTp = 1.0;
                        double dSp = dTp * dTp * (3 - 2 * dTp) * m_dPathLen;   // 경로 전체에 smoothstep
                        int nSeg = 1;
                        while (nSeg < m_adPathCum.Length - 1 && m_adPathCum[nSeg] < dSp) nSeg++;
                        double d0 = m_adPathCum[nSeg - 1], d1 = m_adPathCum[nSeg];
                        double dU = (d1 > d0) ? (dSp - d0) / (d1 - d0) : 1.0;
                        float fPx = (float)(m_afPathPts[nSeg * 3 - 3] + (m_afPathPts[nSeg * 3] - m_afPathPts[nSeg * 3 - 3]) * dU);
                        float fPy = (float)(m_afPathPts[nSeg * 3 - 2] + (m_afPathPts[nSeg * 3 + 1] - m_afPathPts[nSeg * 3 - 2]) * dU);
                        float fPz = (float)(m_afPathPts[nSeg * 3 - 1] + (m_afPathPts[nSeg * 3 + 2] - m_afPathPts[nSeg * 3 - 1]) * dU);
                        // ★처짐 보상 — 틱마다 경로점을 보정 (모델 없으면 그대로). 로그의 tgt 는 보정 전 사용자 경로점.
                        //   명령 속도·가속도(smoothstep 해석식, 세그먼트 접선 방향)를 반경/수직 성분으로 넘겨 주행항까지 보상한다.
                        //   s(τ)=L(3τ²−2τ³) → v = L(6τ−6τ²)/T,  a = L(6−12τ)/T²   (T = 경로 시간, 꺾임점 곡률항은 무시)
                        float fSagVr = 0, fSagVz = 0, fSagAr = 0, fSagAz = 0;
                        {
                            double dTs = m_nPathTime_ms / 1000.0;
                            double dSpeed = m_dPathLen * (6 * dTp - 6 * dTp * dTp) / dTs;
                            double dAccel = m_dPathLen * (6 - 12 * dTp) / (dTs * dTs);
                            double dTx = m_afPathPts[nSeg * 3] - m_afPathPts[nSeg * 3 - 3];
                            double dTy = m_afPathPts[nSeg * 3 + 1] - m_afPathPts[nSeg * 3 - 2];
                            double dTz = m_afPathPts[nSeg * 3 + 2] - m_afPathPts[nSeg * 3 - 1];
                            double dTn = Math.Sqrt(dTx * dTx + dTy * dTy + dTz * dTz);
                            if (dTn > 1e-9) { dTx /= dTn; dTy /= dTn; dTz /= dTn; }
                            double dRr = Math.Sqrt((double)fPx * fPx + (double)fPy * fPy);
                            double dUx = dRr > 1e-6 ? fPx / dRr : 1.0, dUy = dRr > 1e-6 ? fPy / dRr : 0.0;
                            double dTr = dTx * dUx + dTy * dUy;              // 접선의 반경 성분
                            fSagVr = (float)(dSpeed * dTr); fSagVz = (float)(dSpeed * dTz);
                            fSagAr = (float)(dAccel * dTr); fSagAz = (float)(dAccel * dTz);
                        }
                        SagComp_TraceAdd(MotionTick_ms(), fPx, fPy, fPz, fSagVr, fSagVz, fSagAr, fSagAz);   // 주행 측정 중에만 기록
                        float fPxC = fPx, fPyC = fPy, fPzC = fPz;
                        SagComp_Apply(ref fPxC, ref fPyC, ref fPzC, fSagVr, fSagVz, fSagAr, fSagAz);
                        // 한 틱 전진량은 ~1mm — 현재 자세 웜스타트 DLS 라 해가 연속이고 빠르게 수렴.
                        // 굽힘 시드·CCD 폴백은 쓰지 않는다(팔 구성 반전 = 순간이동 방지).
                        // 피치 관리 — 한 경로 안에서는 "단조 완화"만 한다: 실패 시 1도씩 내려
                        // 실현 가능 경계에 붙고, 복귀 시도는 하지 않는다. 경계 지점에서 복귀가
                        // 성공·실패를 오가면(89↔90 플립플롭) 그때마다 손목이 1~2도씩 튀는 것이
                        // 잔여 움찔의 원인이었다(FK 로그 실측: 변1 전환 9회·q14 반전 13회,
                        // 피치 고정인 변3은 관절 반전 0회). 다음 PlayXyzPath 호출은 목표 피치부터 재시작
                        // 완화 스텝 0.25도 — 경계를 정밀하게 찾아 전환 순간의 손목 조정(q14)을
                        // 0.5도 미만으로 유지한다 (1도 스텝이면 전환 한 번에 1.2~1.7도 튐 — 실측)
                        float[] afPSol = null;
                        float fPUse = m_fPathPitchCur;
                        for (int nTry = 0; nTry < 14 && afPSol == null && fPUse >= m_fPathPitch - 30f; nTry++)
                        {
                            afPSol = CalcInv_Tool_Continuous(m_nPathFunc, fPxC, fPyC, fPzC, fPUse, m_nPathWrist, m_anPathPosIDs, 0.3);
                            if (afPSol == null) fPUse -= (nTry < 6) ? 0.25f : 4f;
                        }
                        // 완화가 일어난 틱은 경계에서 0.25도 더 안쪽에 앉는다 — 경계 바로 위에
                        // 올라타면 수렴이 너덜거려 관절 미세 노이즈가 생긴다 (변2 실측: q13 반전 14회)
                        if (afPSol != null && fPUse < m_fPathPitchCur)
                        {
                            float[] afMargin = CalcInv_Tool_Continuous(m_nPathFunc, fPxC, fPyC, fPzC,
                                                                       fPUse - 0.25f, m_nPathWrist, m_anPathPosIDs, 0.3);
                            if (afMargin != null) { afPSol = afMargin; fPUse -= 0.25f; }
                        }
                        if (afPSol != null)
                        {
                            m_fPathPitchCur = fPUse;
                            SetData(m_anPathPosIDs[0], afPSol[0]);
                            SetData(m_anPathPosIDs[1], afPSol[1]);
                            SetData(m_anPathPosIDs[2], afPSol[2]);
                            SetData(m_nPathWrist, afPSol[3]);
                            if (m_MotionSink != null) m_MotionSink(40);   // 실물 스트리밍 등
                        }
                        else if (dTp < 1.0)
                        {
                            // 이 틱은 해가 없다 — 자세를 유지하고 경로 시간도 그만큼 멈춰
                            // 목표가 달아났다 따라잡는 서징(추적오차 수십 mm)을 막는다
                            m_nPathStartTick += MotionTick_ms() - m_nPathLastTick;
                        }
                        // 진단 로그 — 틱별: 경과ms, 적용피치, 목표TCP, 실측TCP(FK), 손목축FK, 관절각
                        if (m_sbPathLog != null && m_sbPathLog.Length < 400000)
                        {
                            float fFx, fFy, fFz, fW2x, fW2y, fW2z;
                            CalcF(m_nPathFunc, -1, false, out fFx, out fFy, out fFz);
                            CalcF(m_nPathFunc, m_nPathWrist, false, out fW2x, out fW2y, out fW2z);
                            m_sbPathLog.AppendFormat(
                                "{0},{1:F1},{2:F2},{3:F2},{4:F2},{5:F2},{6:F2},{7:F2},{8:F2},{9:F2},{10:F2},{11:F2},{12:F2},{13:F2},{14:F2}\r\n",
                                MotionTick_ms() - m_nPathStartTick,
                                afPSol != null ? m_fPathPitchCur : -99f,
                                fPx, fPy, fPz, fFx, fFy, fFz, fW2x, fW2y, fW2z,
                                GetData(m_anPathPosIDs[0]), GetData(m_anPathPosIDs[1]),
                                GetData(m_anPathPosIDs[2]), GetData(m_nPathWrist));
                        }
                        if (dTp >= 1.0) m_bPathRun = false;
                        m_nPathLastTick = MotionTick_ms();
                        return;
                    }
                    if (m_anMoveJointIDs == null) return;
                    double dT = (double)(MotionTick_ms() - m_nMoveJointStartTick) / m_nMoveJointTime_ms;
                    if (dT >= 1.0) dT = 1.0;
                    double dS = dT * dT * (3 - 2 * dT);   // smoothstep
                    for (int i = 0; i < m_anMoveJointIDs.Length; i++)
                        SetData(m_anMoveJointIDs[i],
                                (float)(m_afMoveJointFrom[i] + (m_afMoveJointTo[i] - m_afMoveJointFrom[i]) * dS));
                    if (m_MotionSink != null) m_MotionSink(40);   // 실물 스트리밍 등
                    // 진단 — 관절 보간 중 틱별 TCP (수식 0 기준)
                    if (m_sbPathLog != null && m_sbPathLog.Length < 400000)
                    {
                        float fLx, fLy, fLz;
                        CalcF(0, -1, false, out fLx, out fLy, out fLz);
                        m_sbPathLog.AppendFormat("{0},{1:F2},{2:F2},{3:F2}\r\n",
                            MotionTick_ms() - m_nMoveJointStartTick, fLx, fLy, fLz);
                    }
                    if (dT >= 1.0) m_anMoveJointIDs = null;
                }

                // ── 강의 Play 형식 (블로킹) — 파이썬/워커 스레드용 ──
                /// <summary>Play(시간ms, 딜레이ms, ID,각도, ID,각도, ...) — 지정 시간 동안 부드럽게
                /// 이동하고 끝날 때까지 대기한다. 진행(MoveJoints_Step)은 렌더 틱이 담당하므로
                /// 워커(파이썬) 스레드에서 부를 것. 렌더 틱이 없으면 안전 한도 후 목표각으로 스냅.</summary>
                public bool Play(int nTime_ms, int nDelay_ms, params float[] afVals)
                {
                    if (afVals == null || afVals.Length < 2 || (afVals.Length % 2) != 0) return false;
                    int nCnt = afVals.Length / 2;
                    int[] anIds = new int[nCnt];
                    float[] afDegs = new float[nCnt];
                    for (int i = 0; i < nCnt; i++)
                    {
                        anIds[i] = (int)Math.Round(afVals[i * 2]);
                        afDegs[i] = afVals[i * 2 + 1];
                    }
                    if (!MoveJoints_Start(nTime_ms, anIds, afDegs)) return false;
                    return Play_Wait(nTime_ms, nDelay_ms, anIds, afDegs);
                }

                /// <summary>PlayXyz(시간ms, 딜레이ms, 수식번호, x, y, z, Rx, Ry, Rz, 손목ID, 위치관절 3개...) —
                /// 툴 자세를 3축 각도(도)로 지정해 TCP 를 (x,y,z)로 이동하고 끝날 때까지 대기.
                /// Rx=롤, Ry=피치(90=수직 아래, 0=수평), Rz=요. 현 손목분리 구현은 피치를 손목으로
                /// 실현한다(요=팔 구조상 위치 종속, 롤=롤 관절을 Play 로 별도 제어).
                /// IK 와 보간 전부 라이브러리 내부. 지정 자세 불가 지점은 위치 전용 폴백.</summary>
                public bool PlayXyz(int nTime_ms, int nDelay_ms, int nFunctionNumber,
                                    float fX, float fY, float fZ,
                                    float fRxDeg, float fRyDeg, float fRzDeg,
                                    int nWristID, params int[] anPosMotorIDs)
                {
                    // 현재 TCP 자세·모터 구성 기억 — 이후 축약형 PlayXyz(t,d,수식,x,y,z) / PlayXyzPath(t,d,수식,점배열) 는 "현재 자세 유지" 로 움직인다 (2026-09-22)
                    XyzParam_Remember(nFunctionNumber, fRxDeg, fRyDeg, fRzDeg, nWristID, anPosMotorIDs);
                    if (!MoveTool_Start(nFunctionNumber, fX, fY, fZ, nTime_ms, fRxDeg, fRyDeg, fRzDeg, nWristID, anPosMotorIDs)) return false;
                    bool bOk = Play_Wait(nTime_ms, nDelay_ms, null, null);
                    m_afLastXyzTarget = new[] { fX, fY, fZ };   // ARCH 시작점 추정용
                    return bOk;
                }
                // ※ (자세 생략형: ..., x, y, z, 손목ID, 관절...) 오버로드는 두지 않는다 — 파이썬(pythonnet)에서 정수 인자만 넘기면
                //    짧은 오버로드로 잘못 결합되어(손목ID 자리에 Rx 가 들어감) 조용히 실패한다. 실측 확인.
                //    허용된 형태는 인자 수가 서로 다른 것뿐: 축약형 6 / 중간형 9(자세까지, ID 는 Param 설정) / 긴 형태 10 이상.

                /// <summary>PlayXyzPath(시간ms, 딜레이ms, 수식번호, 점배열[x,y,z 반복], Rx, Ry, Rz, 손목ID, 위치관절 3개)
                /// — 폴리라인 경로를 멈춤 없이 한 획으로 따라가고 끝날 때까지 대기.
                /// 점 사이는 라이브러리가 렌더 틱마다 연속 보간(직선 구간은 끝점 2개면 충분).
                /// PlayXyz 를 점마다 반복하면 점마다 감속·정지·재가속이 생기므로(펌프질처럼 보임),
                /// 그리기 등 선형 연속 동작은 이 함수를 쓴다. 현재 TCP 에서 첫 점까지도 연속으로 잇는다</summary>
                public bool PlayXyzPath(int nTime_ms, int nDelay_ms, int nFunctionNumber,
                                        float[] afXyzPoints,
                                        float fRxDeg, float fRyDeg, float fRzDeg,
                                        int nWristID, int[] anPosMotorIDs)
                {
                    if (afXyzPoints == null || afXyzPoints.Length < 3 || (afXyzPoints.Length % 3) != 0) return false;
                    if (anPosMotorIDs == null || anPosMotorIDs.Length != 3) return false;
                    XyzParam_Remember(nFunctionNumber, fRxDeg, fRyDeg, fRzDeg, nWristID, anPosMotorIDs);   // 현재 자세·구성 기억 (축약형이 이어받음)
                    m_anMoveJointIDs = null;
                    m_bMoveToolPending = false;
                    m_nPathFunc = nFunctionNumber;
                    m_nPathWrist = nWristID;
                    m_anPathPosIDs = (int[])anPosMotorIDs.Clone();
                    m_fPathPitch = fRyDeg;
                    m_fPathPitchCur = fRyDeg;
                    m_nPathTime_ms = Math.Max(1, nTime_ms);
                    m_afPathPtsIn = (float[])afXyzPoints.Clone();
                    m_sbPathLog = new System.Text.StringBuilder(
                        "ms,pitch,tgtx,tgty,tgtz,tcpx,tcpy,tcpz,w14x,w14y,w14z,q0,q1,q2,qw\r\n");
                    m_bPathStarted = false;
                    m_bPathRun = true;                              // 마지막에 세팅 = 활성화
                    bool bOkPath = Play_Wait(nTime_ms, nDelay_ms, null, null);
                    int nLastIdx = afXyzPoints.Length - 3;
                    m_afLastXyzTarget = new[] { afXyzPoints[nLastIdx], afXyzPoints[nLastIdx + 1], afXyzPoints[nLastIdx + 2] };
                    return bOkPath;
                }

                /// <summary>중간형 PlayXyzPath(시간ms, 딜레이ms, 수식, 점배열[x,y,z 반복], Rx, Ry, Rz) —
                /// 손목·위치 관절 ID 는 PlayXyz_Param_TcpId 설정(기본 손목 14, 관절 11·12·13). 인자 수 7 (긴 형태 9)</summary>
                public bool PlayXyzPath(int nTime_ms, int nDelay_ms, int nFunctionNumber, float[] afXyzPoints,
                                        float fRxDeg, float fRyDeg, float fRzDeg)
                {
                    var p = XyzParam(nFunctionNumber);
                    return PlayXyzPath(nTime_ms, nDelay_ms, nFunctionNumber, afXyzPoints, fRxDeg, fRyDeg, fRzDeg, p.nWristID, p.anPosIDs);
                }
                /// <summary>축약형 PlayXyzPath(시간ms, 딜레이ms, 수식, x, y, z) — 점이 하나면 꺽쇠 없이. 현재 TCP 자세·모터 구성 유지. 인자 수 6
                /// (여러 점은 점배열 형태로 — 가변 길이라 꺽쇠가 있어야 뒤의 Rx,Ry,Rz 와 구분된다. 숫자 나열을 아무 개수나 받는 params 형태는
                ///  7인자 중간형에서 꺽쇠를 빠뜨린 호출이 점 2개로 조용히 결합되므로 두지 않는다)</summary>
                public bool PlayXyzPath(int nTime_ms, int nDelay_ms, int nFunctionNumber, float fX, float fY, float fZ)
                {
                    return PlayXyzPath(nTime_ms, nDelay_ms, nFunctionNumber, new float[] { fX, fY, fZ });
                }
                /// <summary>축약형 PlayXyzPath(시간ms, 딜레이ms, 수식, 점배열) — 자세·모터 구성 모두 PlayXyz_Param_* 설정. 인자 수 4</summary>
                public bool PlayXyzPath(int nTime_ms, int nDelay_ms, int nFunctionNumber, float[] afXyzPoints)
                {
                    var p = XyzParam(nFunctionNumber);
                    return PlayXyzPath(nTime_ms, nDelay_ms, nFunctionNumber, afXyzPoints, p.fRx, p.fRy, p.fRz, p.nWristID, p.anPosIDs);
                }

                /// <summary>진단용 — 직전 PlayXyzPath 의 틱별 기록 CSV
                /// (경과ms, 적용피치, 목표TCP, 실측TCP, 손목축FK, 관절각 4개)</summary>
                public string PlayXyzPath_GetLog() { return m_sbPathLog == null ? "" : m_sbPathLog.ToString(); }

                // ================================================================
                // PlayXyz 셋업/동작 분리 + ARCH (2026-08-30)
                // ----------------------------------------------------------------
                // 산업 현장에서 널리 쓰이는 사용 방식(동작 명령과 설정의 분리, 경유 블렌딩,
                // 들어올려 옮기기 자동 경로)을 OpenJigWare 방식으로 구현:
                //   · 동작 명령은 짧게 — PlayXyz(시간, 딜레이, 수식, x, y, z)
                //   · 세부 설정은 수식번호별로 미리 — PlayXyz_Param_*(수식, ...)
                //   · ARCH: 지정 축으로 높이만큼 들어올려 → 수평 이동 → 내려놓는 픽앤플레이스
                //     자동 경로 (축은 x/y/z 사용자 지정)
                //   · PASS: 코너 블렌딩 — "30mm"(코너 앞뒤 거리) 또는 "80%"(직선 유지 비율).
                //     PASS 미설정 = Exact Stop 아님에 주의 — ARCH 경로는 연속 통과(코너 각짐),
                //     정확 정지가 필요하면 명령을 나눠 부른다
                // ================================================================
                private class CXyzParam_t
                {
                    public float fRx = 0, fRy = 90, fRz = 0;       // 툴 자세 기본 = 수직 아래
                    public int nWristID = 14;                       // OMX 기본 손목
                    public int[] anPosIDs = { 11, 12, 13 };         // OMX 기본 위치 관절
                    public float fArchHeight = 0;                   // 0 = ARCH 해제
                    public int nArchAxis = 2;                       // 0=x, 1=y, 2=z
                    public string strPass = null;                   // null = 블렌딩 없음, "30mm"/"80%"
                }
                private System.Collections.Generic.Dictionary<int, CXyzParam_t> m_dicXyzParam =
                    new System.Collections.Generic.Dictionary<int, CXyzParam_t>();
                private float[] m_afLastXyzTarget = null;           // 직전 Play 계열 목표 (ARCH 시작점 추정용)

                private CXyzParam_t XyzParam(int nFunc)
                {
                    CXyzParam_t p;
                    if (!m_dicXyzParam.TryGetValue(nFunc, out p)) { p = new CXyzParam_t(); m_dicXyzParam[nFunc] = p; }
                    return p;
                }
                /// <summary>자세를 명시한 명령(긴 형태·중간형)이 지나갈 때 "현재 TCP 자세·모터 구성" 으로 기억 — 축약형은 이것을 유지한다</summary>
                private void XyzParam_Remember(int nFunc, float fRx, float fRy, float fRz, int nWristID, int[] anPosIDs)
                {
                    var p = XyzParam(nFunc);
                    p.fRx = fRx; p.fRy = fRy; p.fRz = fRz;
                    if (anPosIDs != null && anPosIDs.Length == 3) { p.nWristID = nWristID; p.anPosIDs = (int[])anPosIDs.Clone(); }
                }

                /// <summary>축약 PlayXyz 가 사용할 툴 자세(도) 설정 — Rx=롤, Ry=피치(90=수직 아래), Rz=요</summary>
                public void PlayXyz_Param_Tcp(int nFunctionNumber, float fRxDeg, float fRyDeg, float fRzDeg)
                {
                    var p = XyzParam(nFunctionNumber);
                    p.fRx = fRxDeg; p.fRy = fRyDeg; p.fRz = fRzDeg;
                }

                /// <summary>축약 PlayXyz 가 사용할 모터 구성 설정 — 손목ID + 위치 담당 관절 3개</summary>
                public void PlayXyz_Param_TcpId(int nFunctionNumber, int nWristID, params int[] anPosMotorIDs)
                {
                    if (anPosMotorIDs == null || anPosMotorIDs.Length != 3) return;
                    var p = XyzParam(nFunctionNumber);
                    p.nWristID = nWristID;
                    p.anPosIDs = (int[])anPosMotorIDs.Clone();
                }

                /// <summary>ARCH 설정 — 이후의 축약 PlayXyz 가 '들어올려 → 이동 → 내려놓기' 경로로 움직인다.
                /// fHeight = 안전 이동 높이(mm, 0 = 해제, 음수 = 반대 방향), strAxis = "x"/"y"/"z"(기본 z)</summary>
                public void PlayXyz_Param_Arch(int nFunctionNumber, float fHeight, string strAxis = "z")
                {
                    var p = XyzParam(nFunctionNumber);
                    p.fArchHeight = fHeight;
                    string s = (strAxis == null ? "z" : strAxis).Trim().ToLower();
                    p.nArchAxis = (s == "x") ? 0 : (s == "y") ? 1 : 2;
                }

                /// <summary>PASS(코너 블렌딩) 설정 — "30mm" = 코너 앞뒤 30mm 를 베지어로,
                /// "80%" = 변의 80% 지점까지 직선 후 라운드. null/"" = 블렌딩 해제</summary>
                public void PlayXyz_Param_Pass(int nFunctionNumber, string strBlend)
                {
                    XyzParam(nFunctionNumber).strPass =
                        (strBlend == null || strBlend.Trim().Length == 0) ? null : strBlend.Trim();
                }

                /// <summary>축약형 PlayXyz(시간ms, 딜레이ms, 수식, x, y, z) — 좌표만 주면 "현재 TCP 자세" 를 유지한 채 이동한다.
                /// 현재 자세·모터 구성 = 직전에 자세를 명시한 명령(긴 형태/중간형 PlayXyz·PlayXyzPath)의 값, 또는 PlayXyz_Param_Tcp/_TcpId 로
                /// 움직이지 않고 미리 지정한 값(기본: 수직 아래 0,90,0 / 손목 14 / 관절 11·12·13). ARCH 설정 시 자동 아치 경로,
                /// PASS 설정 시 아치 코너를 블렌딩. 끝날 때까지 대기(블로킹)</summary>
                public bool PlayXyz(int nTime_ms, int nDelay_ms, int nFunctionNumber, float fX, float fY, float fZ)
                {
                    var p = XyzParam(nFunctionNumber);
                    return PlayXyz_WithParamIds(nTime_ms, nDelay_ms, nFunctionNumber, fX, fY, fZ, p.fRx, p.fRy, p.fRz);
                }

                /// <summary>중간형 PlayXyz(시간ms, 딜레이ms, 수식, x, y, z, Rx, Ry, Rz) — 자세는 호출에서 직접 주고,
                /// 그 뒤의 손목·위치 관절 ID 는 PlayXyz_Param_TcpId(수식, 손목, 관절3) 1회 설정을 쓴다(기본 손목 14, 관절 11·12·13).
                /// ARCH/PASS 설정도 축약형과 똑같이 따른다. 인자 수 9 = 긴 형태(10 이상)·축약형(6)과 겹치지 않아
                /// 파이썬(pythonnet)에서도 정수만 넘겨도 바르게 결합된다 (2026-09-22 사용자 요청: 기존 명령은 유지)</summary>
                public bool PlayXyz(int nTime_ms, int nDelay_ms, int nFunctionNumber, float fX, float fY, float fZ,
                                    float fRxDeg, float fRyDeg, float fRzDeg)
                {
                    return PlayXyz_WithParamIds(nTime_ms, nDelay_ms, nFunctionNumber, fX, fY, fZ, fRxDeg, fRyDeg, fRzDeg);
                }

                /// <summary>축약형·중간형 공용: 자세는 인자, 손목·위치 관절은 Param 설정, ARCH/PASS 적용</summary>
                private bool PlayXyz_WithParamIds(int nTime_ms, int nDelay_ms, int nFunctionNumber, float fX, float fY, float fZ,
                                                  float fRx, float fRy, float fRz)
                {
                    var p = XyzParam(nFunctionNumber);
                    bool bOk;
                    if (p.fArchHeight != 0)
                    {
                        // 시작점 = 직전 명령의 목표(없으면 FK 실측 1회)
                        float cx, cy, cz;
                        if (m_afLastXyzTarget != null) { cx = m_afLastXyzTarget[0]; cy = m_afLastXyzTarget[1]; cz = m_afLastXyzTarget[2]; }
                        else CalcF(nFunctionNumber, -1, false, out cx, out cy, out cz);

                        // 아치 축과 수직인 성분(수평 이동량)이 없으면 = 제자리 상하 이동 —
                        // 아치를 걸면 불필요하게 들었다 내리므로 직선으로 처리
                        float[] afDelta = { fX - cx, fY - cy, fZ - cz };
                        afDelta[p.nArchAxis] = 0;
                        double dPerp = Math.Sqrt(afDelta[0] * afDelta[0] + afDelta[1] * afDelta[1] + afDelta[2] * afDelta[2]);
                        if (dPerp < 1.0)
                        {
                            bOk = PlayXyz(nTime_ms, nDelay_ms, nFunctionNumber, fX, fY, fZ,
                                          fRx, fRy, fRz, p.nWristID, p.anPosIDs);
                            m_afLastXyzTarget = new[] { fX, fY, fZ };
                            return bOk;
                        }

                        float[] afLift = { 0, 0, 0 };
                        afLift[p.nArchAxis] = p.fArchHeight;
                        var lstPts = new System.Collections.Generic.List<float[]>
                        {
                            new[] { cx, cy, cz },
                            new[] { cx + afLift[0], cy + afLift[1], cz + afLift[2] },   // 들어올리기
                            new[] { fX + afLift[0], fY + afLift[1], fZ + afLift[2] },   // 수평 이동
                            new[] { fX, fY, fZ }                                        // 내려놓기
                        };
                        var lstPath = (p.strPass != null)
                            ? CMath.SampleCornersSmooth(lstPts, 60, p.strPass, false)   // PASS: 상단 코너 라운드
                            : lstPts;                                                   // 각진 아치 (연속 통과)
                        float[] afFlat = new float[lstPath.Count * 3];
                        for (int i = 0; i < lstPath.Count; i++)
                        {
                            afFlat[i * 3] = lstPath[i][0];
                            afFlat[i * 3 + 1] = lstPath[i][1];
                            afFlat[i * 3 + 2] = lstPath[i][2];
                        }
                        bOk = PlayXyzPath(nTime_ms, nDelay_ms, nFunctionNumber, afFlat, fRx, fRy, fRz, p.nWristID, p.anPosIDs);

                        // 리치 경계 부근에서는 경로 종점 수렴이 늦을 수 있다 —
                        // 오차가 남았으면 목표점 IK 로 짧게 정착시켜 정확히 맺는다
                        float fEx, fEy, fEz;
                        CalcF(nFunctionNumber, -1, false, out fEx, out fEy, out fEz);
                        double dEndErr = Math.Sqrt((fEx - fX) * (fEx - fX) + (fEy - fY) * (fEy - fY) + (fEz - fZ) * (fEz - fZ));
                        if (dEndErr > 0.8)
                            bOk = PlayXyz(Math.Max(150, nTime_ms / 8), 0, nFunctionNumber, fX, fY, fZ,
                                          fRx, fRy, fRz, p.nWristID, p.anPosIDs) && bOk;
                    }
                    else
                    {
                        bOk = PlayXyz(nTime_ms, nDelay_ms, nFunctionNumber, fX, fY, fZ,
                                      fRx, fRy, fRz, p.nWristID, p.anPosIDs);
                    }
                    m_afLastXyzTarget = new[] { fX, fY, fZ };
                    return bOk;
                }

                private bool Play_Wait(int nTime_ms, int nDelay_ms, int[] anIds, float[] afDegs)
                {
                    int nStart = Environment.TickCount;
                    int nLimit = nTime_ms * 3 + 2000;   // 외부 펌프가 죽어 있을 때의 안전 한도
                    while (MoveJoints_IsMoving())
                    {
                        if (!m_bMoveExternalPump)
                        {
                            // 단독 실행(렌더 틱 없음) — 스스로 스텝을 진행한다.
                            // 3D 창 없는 파이썬 단독 스크립트에서도 같은 코드가 같은 시간에 동작
                            MoveJoints_Step();
                            System.Threading.Thread.Sleep(15);
                        }
                        else System.Threading.Thread.Sleep(5);
                        // 안전 한도는 두 모드 공통 — 도달 불가 목표(경로 시간 동결 포함)의 무한 대기 방지
                        if (Environment.TickCount - nStart > nLimit)
                        {
                            MoveJoints_Stop();
                            if (anIds != null)
                                for (int i = 0; i < anIds.Length; i++) SetData(anIds[i], afDegs[i]);
                            break;
                        }
                    }
                    if (nDelay_ms > 0) System.Threading.Thread.Sleep(nDelay_ms);
                    return true;
                }

                #endregion VerticalTool IK + MoveJoints

                private bool m_bIgnoreCheckInit_CalcInv = false;
                private void IgnoreCheckInit_CalcInv(bool bIgnore = true)
                {
                    m_bIgnoreCheckInit_CalcInv = bIgnore;
                }
                public float[] CalcInv_LastOf(bool bIgnoreCheckInit, int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    IgnoreCheckInit_CalcInv();
                    return CalcInv_LastOf(nFunctionNumber, bLimitFunctionNumber, anMotorIDs, fX, fY, fZ, nRepeat, fCutline);
                }
                public float[] CalcInv_LastOf(int nFunctionNumber, bool bLimitFunctionNumber, int[] anMotorIDs, float fX, float fY, float fZ, int nRepeat = 1000, float fCutline = 0.001f)
                {
                    int nID;
                    int nCnt = anMotorIDs.Length;
                    
                    Array.Reverse(anMotorIDs);
                    
                    int nPos = nCnt;
                    float fXc, fYc, fZc;
                    float fXp, fYp, fZp;
                    float fAngle0 = 0;
                    float fP, fN, fC;
                    float fAngle, fAngle1, fAngle2;
                    List<float> lstAngles = new List<float>();
                    for (int i = 0; i < nCnt; i++)
                        lstAngles.Add(GetData(anMotorIDs[i]));
                    float fRes = 0.0f;

                    if (m_bIgnoreCheckInit_CalcInv == false)
                    {
                        // 방향 제한 확인
                        CalcF(nFunctionNumber, -1, false, out fXc, out fYc, out fZc);
                        bool bX = false;
                        bool bY = false;
                        bool bZ = false;
                        for (int i = 0; i < anMotorIDs.Length; i++)
                        {
                            if ((bX == true) && (bY == true) && (bZ == true)) break;

                            float fVal = GetData(anMotorIDs[i]);
                            SetData(anMotorIDs[i], fVal + 10);
                            CalcF(nFunctionNumber, -1, false, out fXp, out fYp, out fZp);
                            if (bX == false) { if (fXc != fXp) { bX = true; } }
                            if (bY == false) { if (fYc != fYp) { bY = true; } }
                            if (bZ == false) { if (fZc != fZp) { bZ = true; } }
                            SetData(anMotorIDs[i], fVal - 10);
                            CalcF(nFunctionNumber, -1, false, out fXp, out fYp, out fZp);
                            if (bX == false) { if (fXc != fXp) { bX = true; } }
                            if (bY == false) { if (fYc != fYp) { bY = true; } }
                            if (bZ == false) { if (fZc != fZp) { bZ = true; } }
                            SetData(anMotorIDs[i], fVal);
                        }
                        if (bX == false) fX = fXc;
                        if (bY == false) fY = fYc;
                        if (bZ == false) fZ = fZc;
                    }
                    if (m_bIgnoreCheckInit_CalcInv == true) m_bIgnoreCheckInit_CalcInv = false;
                    //////////////////////////////////////////////////////////////////
                    for (int nCalc = 0; nCalc < nRepeat; nCalc++)
                    {
                        fRes = 1.0f;
                        nPos = nCnt;
                        while (nPos - 1 >= 0)
                        {
                            nID = anMotorIDs[nPos - 1];
                            fAngle0 = GetData(nID);

                            CalcF_LastOf(nFunctionNumber, -1, bLimitFunctionNumber, out fXc, out fYc, out fZc);
                            CalcF_LastOf(nFunctionNumber, nID, bLimitFunctionNumber, out fXp, out fYp, out fZp);

                            fP = (float)Math.Sqrt(
                                Math.Pow(fX - fXc, 2) +
                                Math.Pow(fY - fYc, 2) +
                                Math.Pow(fZ - fZc, 2)
                                );
                            fN = (float)Math.Sqrt(
                                (float)Math.Pow(fXc - fXp, 2) +
                                (float)Math.Pow(fYc - fYp, 2) +
                                (float)Math.Pow(fZc - fZp, 2)
                                );
                            fC = (float)Math.Sqrt(
                                (float)Math.Pow(fX - fXp, 2) +
                                (float)Math.Pow(fY - fYp, 2) +
                                (float)Math.Pow(fZ - fZp, 2)
                                );
                            fAngle1 = fAngle0 + (float)Ojw.CMath.ACos((fC * fC + fN * fN - fP * fP) / (2.0f * fC * fN));
                            fAngle2 = fAngle0 - ((float)Ojw.CMath.ACos((fC * fC + fN * fN - fP * fP) / (2.0f * fC * fN)));
                            bool bNon1 = false;
                            bool bNon2 = false;
                            if (Single.IsNaN(fAngle1)) { fAngle1 = fAngle0; bNon1 = true; }
                            if (Single.IsNaN(fAngle2)) { fAngle2 = fAngle0; bNon2 = true; }

                            if (bNon1 == false)
                            {
                                // Distance 계산
                                SetData(nID, fAngle1);
                                CalcF_LastOf(nFunctionNumber, -1, bLimitFunctionNumber, out fXc, out fYc, out fZc);
                                fC = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXc, 2) +
                                    (float)Math.Pow(fY - fYc, 2) +
                                    (float)Math.Pow(fZ - fZc, 2)
                                    );
                            }
                            else fC = 99999999f;

                            if (bNon2 == false)
                            {
                                SetData(nID, fAngle2);
                                CalcF_LastOf(nFunctionNumber, -1, bLimitFunctionNumber, out fXp, out fYp, out fZp);
                                fP = (float)Math.Sqrt(
                                    (float)Math.Pow(fX - fXp, 2) +
                                    (float)Math.Pow(fY - fYp, 2) +
                                    (float)Math.Pow(fZ - fZp, 2)
                                    );
                            }
                            else fP = 99999999f;


                            if ((fAngle1 < 0) && (fAngle2 > 0))
                            {
                                if (fAngle0 > 0) fAngle = fAngle2;
                                else fAngle = fAngle1;
                            }
                            else if ((fAngle2 < 0) && (fAngle1 > 0))
                            {
                                if (fAngle0 > 0) fAngle = fAngle1;
                                else fAngle = fAngle2;
                            }
                            else fAngle = CalcLimit(nID, (fC < fP) ? fAngle1 : fAngle2);

                            SetData(nID, fAngle);

                            fRes = 0;
                            for (int i = 0; i < nCnt; i++)
                            {
                                fRes += (float)Math.Abs(GetData(anMotorIDs[i]) - lstAngles[i]);
                                lstAngles[i] = GetData(anMotorIDs[i]);
                            }
                            nPos--;
                        }

                        if (fRes < fCutline) break;
                    }
                    float[] afRes = lstAngles.ToArray();
                    Array.Reverse(afRes);
                    return afRes;
                }
