                    m_rtxtDraw.TextChanged += new System.EventHandler(m_rtxtDraw_TextChanged);
                    m_rtxtDraw.KeyDown += new KeyEventHandler(m_rtxtDraw_KeyDown);
                    m_rtxtDraw.MouseDown += new MouseEventHandler(m_rtxtDraw_MouseDown);
                }
