                private int m_nMouseControlMode = 1;// 0;
                public void SetMouseMode_Move() { SetMouseMode(0); }
                public void SetMouseMode_Control() { SetMouseMode(1); }
                public void SetMouseMode_Ext() { SetMouseMode(2); }
