                                    }
                                }
                            }
#else
                            if (m_bGridInit == true)
                            {
                                for (int i = 0; i < m_CHeader.nMotorCnt; i++)
                                {
                                    GridMotionEditor_SetMotor(GridMotionEditor_GetCurrentLine(), i, GetData(i));
                                }
                            }
                            if (m_CGridMotionEditor != null)
                            {
                                if (m_CGridMotionEditor.m_nGridMode == 1)
                                {
                                    if (m_CHeader != null)
                                    {
                                        for (int i = 0; i < m_CHeader.nMotorCnt; i++)
                                        {
                                            //GridMotionEditor_SetMotor(GridMotionEditor_GetCurrentLine(), i, GetData(i));

                                            int nID = m_CHeader.anMotorIDs[i];
                                            if (nID < 0) continue;
                                            if ((m_CHeader.pSMotorInfo[nID].nMotor_Enable < 0) || (m_CHeader.pSMotorInfo[nID].nMotor_Enable > 1))
                                                continue;
                                            try
                                            {
                                                SetData(nID, GridMotionEditor_GetMotor(GridMotionEditor_GetCurrentLine(), nID));
                                            }
                                            catch
                                            {
                                                float fValue = GetData(nID);
                                                SetData(nID, fValue);
                                            }
                                        }
                                    }
                                }
                            }
#endif
                            m_nMouse_X_Left = e.X;
                            m_nMouse_Y_Left = e.Y;                            
                        }
                        else if (e.Button == MouseButtons.Right)
                        {
                            // 선택 오브젝트가 있으면 그 중심을 orbit 피벗으로 (드래그 시작 시 1회 확정)
                            float fPanOld = m_fPan, fTiltOld = m_fTilt, fSwingOld = m_fSwing;
                            if (m_bOrbitPivotHeld == false)
                            {
                                lock (m_oPivotLock)
                                {
                                    if ((m_lDrawSeq - m_lSelPivotSeq) < 3)   // 최근 프레임에 선택 오브젝트가 그려졌나
                                    {
                                        // p = Rᵀ·(obj − c),  V_T = [R|c] (column-major)
                                        double vx = m_adSelObjMat[12] - m_adViewTMat[12];
                                        double vy = m_adSelObjMat[13] - m_adViewTMat[13];
                                        double vz = m_adSelObjMat[14] - m_adViewTMat[14];
                                        m_adOrbitDragPivot[0] = m_adViewTMat[0] * vx + m_adViewTMat[1] * vy + m_adViewTMat[2] * vz;
                                        m_adOrbitDragPivot[1] = m_adViewTMat[4] * vx + m_adViewTMat[5] * vy + m_adViewTMat[6] * vz;
                                        m_adOrbitDragPivot[2] = m_adViewTMat[8] * vx + m_adViewTMat[9] * vy + m_adViewTMat[10] * vz;
                                        m_bOrbitPivotHeld = true;
                                    }
                                }
                            }
                            if (m_nCoordMode == 1)
                            {
                                // 로봇 좌표 모드: 좌우 드래그 → Z축 회전(Swing=Yaw), 상하 드래그 → Y축 회전(Pan=Pitch)
                                if (GetFreeze_Swing() == false) m_fSwing -= (m_nMouse_X_Right - e.X);
                                if (GetFreeze_Pan()   == false) m_fPan   -= (m_nMouse_Y_Right - e.Y);
                            }
                            else
                            {
                                if (GetFreeze_Pan() != true) m_fPan -= (m_nMouse_X_Right - e.X);
                                if (GetFreeze_Tilt() != true) m_fTilt -= (m_nMouse_Y_Right - e.Y);
                                if ((GetFreeze_Pan() == true) && (GetFreeze_Tilt() == true) && (GetFreeze_Swing() == false))
                                {
                                    m_fSwing -= (m_nMouse_X_Right - e.X);
                                }
                            }
                            if (m_fTilt < 0) m_fTilt += 360;
                            if (m_fPan < 0) m_fPan += 360;
                            if (m_fTilt >= 360) m_fTilt -= 360;
                            if (m_fPan >= 360) m_fPan -= 360;
                            if (m_bOrbitPivotHeld &&
                                ((fPanOld != m_fPan) || (fTiltOld != m_fTilt) || (fSwingOld != m_fSwing)))
                            {
                                // 피벗 p 의 화면 위치가 회전 후에도 유지되도록 t 재계산:
                                //   v = R_old·(p + t_old),  t_new = R_new⁻¹·v − p
                                // Forward R = Ry(Pan)·Rx(Tilt)·Rz(Swing) — 벡터엔 Z→X→Y 순 적용,
                                // Inverse 는 Y(-P)→X(-T)→Z(-S) (기존 역변환 코드와 동일 규약).
                                double x = m_adOrbitDragPivot[0] + m_fX;
                                double y = m_adOrbitDragPivot[1] + m_fY;
                                double z = m_adOrbitDragPivot[2] + m_fZ;
                                CMath.CalcRot(0, 0, (double)fSwingOld, ref x, ref y, ref z);
                                CMath.CalcRot((double)fTiltOld, 0, 0, ref x, ref y, ref z);
                                CMath.CalcRot(0, (double)fPanOld, 0, ref x, ref y, ref z);
                                CMath.CalcRot(0, (double)(-m_fPan), 0, ref x, ref y, ref z);
                                CMath.CalcRot((double)(-m_fTilt), 0, 0, ref x, ref y, ref z);
                                CMath.CalcRot(0, 0, (double)(-m_fSwing), ref x, ref y, ref z);
                                if (GetFreeze_X() == false) m_fX = (float)(x - m_adOrbitDragPivot[0]);
                                if (GetFreeze_Y() == false) m_fY = (float)(y - m_adOrbitDragPivot[1]);
                                if (GetFreeze_Z() == false) m_fZ = (float)(z - m_adOrbitDragPivot[2]);
                            }
                            if (GetMouseMode() == 0)
                            {
                                //if ((m_nMouse_X_Right == e.X) && (m_nMouse_Y_Right == e.Y)) m_nMenuStatus = 1;
                                //else m_nMenuStatus = 0;
                                if ((m_nMouse_X_Right != e.X) || (m_nMouse_Y_Right != e.Y)) m_nMenuStatus = 0;
                            }
                            else
                            {
                                m_nMenuStatus = 0;
                            }
                            m_nMouse_X_Right = e.X;
                            m_nMouse_Y_Right = e.Y;
                        }
                        else
                        {
                        }
                        //OjwDraw();
                    }
                }
