                public void SetPerspectiveMode(bool bOn) { m_nPerspectiveMode = ((bOn  == true) ? 1 : 0); } // 보이는 뷰를 원근 뷰로 전환
                public bool IsPerspectiveMode() { return ((m_nPerspectiveMode == 1) ? true : false); }

