                                                        0x10 | // Enable
                                                        ((m_CHeader.pSMotorInfo[j].nMotorControlType != 0) ? 0x08 : 0x00)// 위치제어가 아니라면 //0x08 //| // MotorType
                                                        //0x07 // Led
                                                        );
                                                }
                                            }

                                            CheckFlag(m_CGridMotionEditor.m_nCurrntCell);
