                                                                m_CGridMotionEditor.SetData5(nLine, nTmp);
                                                            }
                                                            nCommand = 0;
                                                        }
                                                    }
                                                    //strTmp += pstrValue[i + nOffset_i, j + nOffset_j] + "[]";
                                                }
