                                                            Ojw.CGridView.Grid_Xyz2Angle(this, nLine, nFunction, afX[nFunction], afY[nFunction], afZ[nFunction]);
                                                        }
                                                    }
                                                    break;
                                                case "@SET_INC":
                                                    {
                                                        if (pstrFunctions.Length >= 4)
                                                        {
                                                            int nFunction = Ojw.CConvert.StrToInt(pstrFunctions[nIndex++]);
