                                                            float fY = Ojw.CConvert.StrToFloat(pstrFunctions[nIndex++]);
                                                            float fZ = Ojw.CConvert.StrToFloat(pstrFunctions[nIndex++]);

                                                            #region Read Forward
                                                            // 결과가 나오기 보다는 결과를 메모리에 올리기만 한다.
                                                            float[] afMot = new float[m_CHeader.nMotorCnt];
