                            {
                                if (m_bDhSkeleton_Direction_Show == false)
                                {
                                    bShow = false;
                                }
                            }
                            if (bShow)
                            {
                                if ((CDisp.nName >= 0) && (afData.Length > CDisp.nName))
                                    CDisp.fAngle = afData[CDisp.nName];// +GetData(CDisp.nName);

