                        }
#endif



                        //SwapBuffers();
                        glFlush();
                        m_lDrawSeq++;   // orbit 피벗 신선도 판정용 프레임 시퀀스
                        //Refresh();
                        SwapBuffers();
                        //this.SwapBuffers();
