                    OjwTranslate(m_fX, m_fY, m_fZ);
                    lock (m_oPivotLock) { Gl.glGetDoublev(Gl.GL_MODELVIEW_MATRIX, m_adViewTMat); } // 뷰 변환 직후 = 씬 프레임 기준행렬
