                public void User_SetDhSphereEnabled(bool bShow) { m_bUser_ShowDhSphere = bShow; }

                // === Screen → World 좌표 변환 ($scene placement 용) ============================
                //   OjwDraw 의 매 frame 끝부분에서 GL matrices/viewport 를 캐싱해 두고,
                //   외부 (MakeUrdf 의 OnC3dMouseDown 등) 가 마우스 픽셀 좌표 → 월드 Z=0 평면 좌표로
                //   변환하도록 노출한다. mm 단위 (3D 뷰 내부 좌표계 그대로).
                private double[] m_adCachedModelview = new double[16];
                private double[] m_adCachedProj      = new double[16];
                private int[]    m_aiCachedViewport  = new int[4];
                private bool     m_bMatricesCached   = false;

                private void CacheGLMatrices()
                {
                    try
                    {
                        Gl.glGetDoublev(Gl.GL_MODELVIEW_MATRIX, m_adCachedModelview);
                        Gl.glGetDoublev(Gl.GL_PROJECTION_MATRIX, m_adCachedProj);
                        Gl.glGetIntegerv(Gl.GL_VIEWPORT, m_aiCachedViewport);
                        m_bMatricesCached = true;
                    }
                    catch { }
                }

                // ── 선택 오브젝트 중심 orbit ──────────────────────────────────
                //   기본 회전의 고정점은 "화면중심 광선 ∩ 바닥"이라 pan 후에는 로봇이
                //   pan 거리만큼의 반경으로 공전한다. 오브젝트가 선택돼 있으면(EDH 라인
                //   하이라이트) 그 부품의 중심을 피벗으로 쓴다:
                //   렌더 스레드가 ①뷰 변환 직후 행렬 V_T ②선택 오브젝트를 그리는 순간의
                //   행렬 M_obj 를 캡처 → inv(V_T)·M_obj 의 평행이동 = 부품의 씬 좌표.
                //   회전 시 그 점의 화면 위치가 고정되도록 t(m_fX/Y/Z)를 재계산한다.
                //   선택이 없으면 기존 동작 그대로.
                private readonly object m_oPivotLock = new object();
                private bool m_bSelPivotArm = false;          // 렌더 루프: 지금 그리는 게 선택 오브젝트
                private long m_lDrawSeq = 0;                  // 프레임 시퀀스 (glDraw_End 증가)
                private long m_lSelPivotSeq = -1000;          // 마지막 캡처 프레임
                private bool m_bOrbitPivotHeld = false;       // 드래그 동안 피벗 고정
                private double[] m_adSelObjMat = new double[16];
                private double[] m_adViewTMat = new double[16];
                private double[] m_adOrbitDragPivot = new double[3];
                private bool m_bOrbitHeldPrev = false;        // 직전 드래그에서 피벗이 잡혔었나 (진단용)

                /// <summary>orbit 피벗 상태 진단 문자열 (임시 — 원인 확정 후 제거 가능)</summary>
                public string GetOrbitDebug()
                {
                    lock (m_oPivotLock)
                    {
                        return string.Format(
                            "drawSeq={0} selSeq={1} (diff={2}) heldPrev={3} selIdx={4} pivot=({5:F1},{6:F1},{7:F1}) viewT=({8:F1},{9:F1},{10:F1})",
                            m_lDrawSeq, m_lSelPivotSeq, m_lDrawSeq - m_lSelPivotSeq, m_bOrbitHeldPrev,
                            m_nUser_SelectedIndex,
                            m_adOrbitDragPivot[0], m_adOrbitDragPivot[1], m_adOrbitDragPivot[2],
                            m_adViewTMat[12], m_adViewTMat[13], m_adViewTMat[14]);
                    }
                }

                /// <summary>
                /// 월드 좌표 → WinForms 스크린 좌표 (top-down Y).
                ///   gluProject 결과 (GL bottom-up Y) 를 WinForms top-down 으로 변환.
                ///   반환 false: 캐싱 안 됨 / project 실패.
                ///   실제 render 시점의 modelview/projection 매트릭스 (카메라+로봇 회전 모두 포함) 사용.
                /// </summary>
                public bool WorldToScreen(double wx, double wy, double wz,
                                          out double screenX, out double screenY)
                {
                    screenX = screenY = 0;
                    if (m_bMatricesCached == false) return false;
                    try
                    {
                        double sx, sy, sz;
                        if (Glu.gluProject(wx, wy, wz,
                            m_adCachedModelview, m_adCachedProj, m_aiCachedViewport,
                            out sx, out sy, out sz) == 0) return false;
                        screenX = sx;
                        // gluProject 의 Y 는 GL bottom-up → WinForms top-down 으로 변환
                        screenY = m_aiCachedViewport[3] - sy;
                        return true;
                    }
                    catch { return false; }
                }

                /// <summary>
                /// WinForms 마우스 좌표 (top-down) → 월드 raycast 광선.
                ///   gluUnProject 의 near plane (z=0) 점 + far plane (z=1) 점 으로 광선 구성.
                ///   반환 false: 캐싱 안 됨 / unproject 실패.
                ///   GetOrthoRay 보다 정확 (실제 카메라 행렬을 그대로 사용).
                /// </summary>
                public bool ScreenToWorldRay(int screenX, int screenY,
                                             out double ox, out double oy, out double oz,
                                             out double dx, out double dy, out double dz)
                {
                    ox = oy = oz = dx = dy = dz = 0;
                    if (m_bMatricesCached == false) return false;
                    try
                    {
                        int viewH = m_aiCachedViewport[3];
                        int glY = viewH - screenY;   // WinForms top-down → GL bottom-up

                        double nearX, nearY, nearZ;
                        double farX,  farY,  farZ;
                        Glu.gluUnProject(screenX, glY, 0.0,
                                         m_adCachedModelview, m_adCachedProj, m_aiCachedViewport,
                                         out nearX, out nearY, out nearZ);
                        Glu.gluUnProject(screenX, glY, 1.0,
                                         m_adCachedModelview, m_adCachedProj, m_aiCachedViewport,
                                         out farX,  out farY,  out farZ);

                        ox = nearX; oy = nearY; oz = nearZ;
                        double rx = farX - nearX, ry = farY - nearY, rz = farZ - nearZ;
                        double rl = Math.Sqrt(rx * rx + ry * ry + rz * rz);
                        if (rl < 1e-9) return false;
                        dx = rx / rl; dy = ry / rl; dz = rz / rl;
                        return true;
                    }
                    catch { return false; }
                }

                /// <summary>
                /// WinForms 마우스 좌표 (top-down) → 월드 Z=0 평면 위 좌표 (mm).
                ///   internal: gluUnProject 로 near/far ray 두 점 → Z=0 평면과 교차.
                ///   반환 false: 캐싱 안 됨 / 광선이 floor 와 평행 / 교차점이 카메라 뒤편.
                /// </summary>
                public bool ScreenToWorldOnFloor(int screenX, int screenY,
                                                 out double wx, out double wy, out double wz)
                {
                    wx = wy = wz = 0;
                    if (m_bMatricesCached == false) return false;
                    try
                    {
                        int viewH = m_aiCachedViewport[3];
                        int glY = viewH - screenY;   // WinForms top-down → GL bottom-up

                        double nearX, nearY, nearZ;
                        double farX,  farY,  farZ;
                        Glu.gluUnProject(screenX, glY, 0.0,
                                         m_adCachedModelview, m_adCachedProj, m_aiCachedViewport,
                                         out nearX, out nearY, out nearZ);
                        Glu.gluUnProject(screenX, glY, 1.0,
                                         m_adCachedModelview, m_adCachedProj, m_aiCachedViewport,
                                         out farX,  out farY,  out farZ);

                        // Z=0 평면과 광선 교차: z(t) = nearZ + t*(farZ - nearZ) = 0
                        double dz = farZ - nearZ;
                        if (Math.Abs(dz) < 1e-9) return false;
                        double t = -nearZ / dz;
                        if (t < 0) return false;
                        wx = nearX + t * (farX - nearX);
                        wy = nearY + t * (farY - nearY);
                        wz = 0;
                        return true;
                    }
                    catch { return false; }
                }

