                                else if (astr[nOff] == ">=") { nMode = 26; nArg = 4; } // >=;a;b;c;d     a 가 b 보다 크거나 같으면 결과에 c를 입력 아니면 d를 입력
                                else if (astr[nOff] == "<=") { nMode = 27; nArg = 4; } // <=;a;b;c;d     a 가 b 보다 작거나 같으면 결과에 c를 입력 아니면 d를 입력
