                                else if (astr[nOff] == "<") { nMode = 29; nArg = 4; } // <=;a;b;c;d      a 가 b 보다 작으면 결과에 c를 입력 아니면 d를 입력
                                else if (astr[nOff] == "deltainit") { nMode = 30; nArg = 4; } // deltainit;윗판Rad;윗링크;아래링크;아래판Rad — 델타 기하 등록
                                else if (astr[nOff] == "getdelta") { nMode = 31; nArg = 5; } // getdelta;팔(0~2);sel(0=β,1=γ,2~4=x/y/z);m0;m1;m2 — 델타 종동각/FK (결과 deg 또는 mm)
