                                    //    {
                                    //        if ((CDisp.nDispModel >= 0x1000) && (CDisp.nDispModel < 0x2000))
                                    //        {
                                    //            CDisp.strDispObject = CConvert.IntToStr(CConvert.StrToInt(strItem) - 0x1000);
                                    //            CDisp.nDispModel = 0x1000;
                                    //        }
                                    //        else
