                        fLength_Out = (float)Math.Sqrt(fLength * fLength - (fR1 - fR) * (fR1 - fR));
                        float fAngleGap = (float)Ojw.CMath.ATan2(fLength, (fR1 - fR));
                        float fTmp = (fAngle - fAngle2 + 360.0f) % 360.0f;
