                            //    nNum_Next = (j < nCnt - 1) ? (j + 1) : (j - nCnt + 1);
                            //    nNum_Next2 = ((j < nCnt - 2) ? (j + 2) : (j - nCnt + 2)) % nCnt;
                            //    aSValue[nNum_Next].fX = aSValue[nNum_Next2].fX;
