                                               0, 0, 0, fPos, 0, -fTrack_W / 2.0f);
                                    OjwBox_Outside(bFill, color, fAlpha, fTrack_Distance, 10, fTrack_W,
                                            0, 0, 0, fPos, 0, 0);//-fTrack_W / 2.0f);
                                }
                                fPos += fTrack_Distance;
                            }
                        }
                        OjwRotation(0, 0, -fAngleGap);
                        OjwTranslate(0, -fR, 0);
