                    if (strIndex.IndexOf('.') < 0) strIndex += ".dat";
#else
                    // Default -> ase
                    if (strIndex.IndexOf('.') < 0) strIndex += ".ase";
#endif
                    for (int i = 0; i < m_lstModel.Count; i++)
                    {
                        if (m_lstModel[i] == strIndex) { nIndex = i; break; }
                    }
                    return nIndex;
#else
                    int nIndex = -1;
                    for (int i = 0; i < m_lstModel.Count; i++)
                    {
                        if (m_lstModel[i] == strIndex) { nIndex = i; break; }
                    }
                    return nIndex;
#endif
