                    m_fColor[1] = ((float)cColor.G / 255.0f);  // G
                    m_fColor[2] = ((float)cColor.B / 255.0f);  // B
                    m_fColor[3] = fAlpha;// m_fAlpha;

                    Gl.glPushMatrix();
                    OjwTranslate(fOffsetX, fOffsetY, fOffsetZ);
                    OjwRotation(0, 0, fOffsetSwing);
                    OjwRotation(0, fOffsetTilt, 0);
                    OjwRotation(fOffsetPan, 0, 0);

                    //Gl.glPushMatrix();
                    //SetLight();
                    //SetLight2();
                    //SetLight3();

                    Gl.glFrontFace(((bDat == true) ? Gl.GL_CW : Gl.GL_CCW)); // 20150528 수정 - 이게 맞다.
                    Gl.glFrontFace(((bDat == true) ? Gl.GL_CW : Gl.GL_CCW)); // 20150528 수정 - 이게 맞다.

                    Gl.glEnable(Gl.GL_DEPTH_TEST);
                    Gl.glDisable(Gl.GL_CULL_FACE);
                    
                    // 1단계: 앞면을 채워진 색으로
                    //float[] fillColorArray = { (float)fillColor.R / 255.0f, (float)fillColor.G / 255.0f, 
                    //          (float)fillColor.B / 255.0f, fAlpha };

                    //if (IsPerspectiveMode() == true)
                    //{
                    //    Gl.glPolygonMode(Gl.GL_FRONT,
                    //            (int)(
                    //                (bFill == true) ?
                    //                    Gl.GL_FILL : Gl.GL_LINE
                    //            )
                    //        );


                    //    Gl.glPolygonMode(Gl.GL_BACK, (int)((bFill == true) ? ((m_bDetail == true) ? Gl.GL_LINE : Gl.GL_LINE) : ((m_bDetail == true) ? Gl.GL_LINE : Gl.GL_POINT)));

                    //}
                    // 앞뒤 모두 채우기 (STL 와인딩 불규칙 대응)
                    Gl.glPolygonMode(Gl.GL_FRONT_AND_BACK,
                                (int)((bFill == true) ? Gl.GL_FILL : Gl.GL_LINE));

                    if (bStl == true)
                    {
                        // STL: 조명 끄고 수동 음영 계산 (와인딩 불규칙 대응)
                        //   2026-08-25: 셰이딩 포함 지오메트리를 디스플레이 리스트로 캐시 —
                        //   대형 메시도 프레임당 glCallList 한 번 (외관 동일, 색별 캐시)
                        Gl.glDisable(Gl.GL_LIGHTING);
                        float baseR = m_fColor[0], baseG = m_fColor[1], baseB = m_fColor[2];

                        int nAlpha255 = (int)(m_fColor[3] * 255.0f);
                        long lKeyFill = MeshList_Key(nIndex_Ase, cColor.ToArgb(), nAlpha255, 0);
                        int nListFill;
                        if (m_dictMeshList.TryGetValue(lKeyFill, out nListFill) == false)
                        {
                            // 조명 방향 (정규화된 고정 벡터)
                            float lx = 0.577f, ly = 0.577f, lz = 0.577f;
                            nListFill = Gl.glGenLists(1);
                            Gl.glNewList(nListFill, Gl.GL_COMPILE);
                            Gl.glBegin(Gl.GL_TRIANGLES);
                            SVector4D_t[] vertices = m_lstOjwAse[nIndex_Ase].Data_Get();
                            for (int i = 0; i < vertices.Length; i += 3)
                            {
                                if (i + 2 >= vertices.Length) break;
                                // 면 법선 계산
                                float ex = vertices[i + 1].x - vertices[i].x;
                                float ey = vertices[i + 1].y - vertices[i].y;
                                float ez = vertices[i + 1].z - vertices[i].z;
                                float fx = vertices[i + 2].x - vertices[i].x;
                                float fy = vertices[i + 2].y - vertices[i].y;
                                float fz = vertices[i + 2].z - vertices[i].z;
                                float nx = ey * fz - ez * fy;
                                float ny = ez * fx - ex * fz;
                                float nz = ex * fy - ey * fx;
                                // 정규화
                                float len = (float)Math.Sqrt(nx * nx + ny * ny + nz * nz);
                                if (len > 0.0001f) { nx /= len; ny /= len; nz /= len; }
                                // dot product (절대값 → 와인딩 무관)
                                float dot = Math.Abs(nx * lx + ny * ly + nz * lz);
                                float shade = 0.3f + 0.7f * dot; // ambient 0.3 + diffuse 0.7
                                Gl.glColor4f(baseR * shade, baseG * shade, baseB * shade, m_fColor[3]);
                                Gl.glVertex3f(vertices[i].x, vertices[i].y, vertices[i].z);
                                Gl.glVertex3f(vertices[i + 1].x, vertices[i + 1].y, vertices[i + 1].z);
                                Gl.glVertex3f(vertices[i + 2].x, vertices[i + 2].y, vertices[i + 2].z);
                            }
                            Gl.glEnd();
                            Gl.glEndList();
                            MeshList_Register(lKeyFill, nListFill);
                        }
                        Gl.glCallList(nListFill);

                        // 어두운 모델만 실루엣 윤곽선 추가
