                            Gl.glPolygonMode(Gl.GL_FRONT_AND_BACK, Gl.GL_LINE);
                            Gl.glLineWidth(1.5f);
                            Gl.glColor4f(0.25f, 0.25f, 0.25f, m_fColor[3]);
                            // 색 무관 지오메트리 전용 리스트 (variant 2) — 실루엣/기타 색상 재사용
                            long lKeyGeo = MeshList_Key(nIndex_Ase, 0, 0, 2);
