                                for (int i = 0; i < vertices2.Length; i += 3)
                                {
                                    if (i + 2 >= vertices2.Length) break;
                                    Gl.glVertex3f(vertices2[i].x, vertices2[i].y, vertices2[i].z);
                                    Gl.glVertex3f(vertices2[i + 1].x, vertices2[i + 1].y, vertices2[i + 1].z);
                                    Gl.glVertex3f(vertices2[i + 2].x, vertices2[i + 2].y, vertices2[i + 2].z);
                                }
                                Gl.glEnd();
                                Gl.glEndList();
                                MeshList_Register(lKeyGeo, nListGeo);
                            }
                            Gl.glCallList(nListGeo);
                            Gl.glCullFace(Gl.GL_BACK);  // 기본값 복원
                            Gl.glPolygonMode(Gl.GL_FRONT_AND_BACK, Gl.GL_FILL);
                            Gl.glLineWidth(1.0f);
                        }

                        Gl.glEnable(Gl.GL_LIGHTING);
                    }
                    else
