                /// <summary>
                /// Design 3d에 표시된 객체들을 바탕으로 URDF 생성
                /// MakeDHSkeleton 호출 후 사용해야 함
                /// </summary>
                public string BuildUrdfFromDisplayObjects(string robotName)
                {
                    var urdfBuilder = new COjwUrdfBuilder_t();
                    urdfBuilder.RobotName = robotName;
                    urdfBuilder.SetWorldFixed();

                    int cnt = User_GetCnt();
                    int jointCounter = 0;

                    for (int i = 0; i < cnt; i++)
                    {
                        COjwDisp disp = User_Get(i);
                        if (disp == null) continue;

                        // 위치/회전 정보 (mm -> m, degree -> radian)
                        double x = disp.afTrans[0].x * 0.001;
                        double y = disp.afTrans[0].y * 0.001;
                        double z = disp.afTrans[0].z * 0.001;
                        double roll = disp.afRot[0].pan * Math.PI / 180.0;
                        double pitch = disp.afRot[0].tilt * Math.PI / 180.0;
                        double yaw = disp.afRot[0].swing * Math.PI / 180.0;

                        // 색상
                        uint color = (uint)((disp.cColor.R << 16) | (disp.cColor.G << 8) | disp.cColor.B);

                        string objType = disp.strDispObject ?? "";

                        if (objType == "#8" || objType == "#19") // cylinder (bar)
                        {
                            double radius = disp.fWidth_Or_Radius * 0.001;
                            double length = disp.fHeight_Or_Depth * 0.001;
                            if (length > 0.0001)
                            {
                                urdfBuilder.AddCylinderAsRod("cyl_" + i, x, y, z, roll, pitch, yaw,
                                    Math.Max(radius, 0.001), Math.Max(length, 0.001), color);
                            }
                        }
                        else if (objType == "#9" || objType == "#20") // sphere (ball)
                        {
                            double radius = disp.fWidth_Or_Radius * 0.001;
                            urdfBuilder.AddSphere("sph_" + i, x, y, z, roll, pitch, yaw,
                                Math.Max(radius, 0.001), color);
                        }
                        else if (objType.EndsWith(".stl", StringComparison.OrdinalIgnoreCase) ||
                                 objType.EndsWith(".obj", StringComparison.OrdinalIgnoreCase) ||
                                 objType.EndsWith(".ase", StringComparison.OrdinalIgnoreCase))
                        {
                            // STL/OBJ/ASE mesh
                            double scale = 0.001; // mm -> m
                            urdfBuilder.AddMesh("mesh_" + i, x, y, z, roll, pitch, yaw,
                                "stl/" + objType, scale, scale, scale, color);
                        }

                        // Joint 처리 (nName >= 0이면 모터 축)
                        if (disp.nName >= 0)
                        {
                            string jname = "joint_" + jointCounter++;
                            double ax = 0, ay = 0, az = 1; // 기본 Z축 회전
                            if (disp.nDir == 1) az = -1; // 역방향
                            urdfBuilder.AddJoint(jname, JointType.Revolute, x, y, z, roll, pitch, yaw, ax, ay, az);
                        }
                    }

                    return urdfBuilder.Build();
                }
