            private bool File_MakeURDF(string strTitle, string strFileName, string[] astrGuide, string[] astrGroupName)
            {
                string str = "Input yout function number";
                int nFunction = -1;
                scanf(ref str);
                if (Ojw.CConvert.IsDigit(str))
                {
                    try
                    {
                        nFunction = Ojw.CConvert.StrToInt(str);
                        string strDh = m_CHeader.pstrKinematics[nFunction];

                        Ojw.C3d.CUrdf COjwUrdf = new Ojw.C3d.CUrdf();
                        //if (GetAseFile_Path().Length > 0)
                        //{
                        //    COjwUrdf.SetPath_Stl("stl"); // stl이 저장된 폴더의 경로 지정
                        //}                        
                        string urdf = COjwUrdf.MakeDHSkeleton_URDF(strDh, "ojw_robot");
                        Ojw.CFile COjwFile = new Ojw.CFile();
                        COjwFile.Add_Raw(urdf);
                        if (strFileName.ToLower().IndexOf(".urdf") == (strFileName.Length - 5))
                        {

                        }
                        else
                        {
                            strFileName += ".urdf";
                        }
                        COjwFile.Save(strFileName);
                        MessageBox.Show("Save your file -> robot.urdf");
                    }
                    catch (Exception ex)
                    {
                        CMessage.Write(ex.Message);
                    }
                }
                return ((nFunction < 0) ? false : true);
            }
