            private int m_nCnt_Forward = 0;
            private int m_nCnt_Inverse = 0;
            private List<int> lstForward = new List<int>();
            private List<int> lstInverse = new List<int>();
            public int[] GetForward_Numbers() { return lstForward.ToArray(); }
            public int[] GetInverse_Numbers() { return lstInverse.ToArray(); }
            public void GetCount_Kinematics(out int Forward, out int Inverse)
            {
                Forward = m_nCnt_Forward;
                Inverse = m_nCnt_Inverse;
            }
            public void CheckForward()
            {
                int nPos = 0;
                m_nCnt_Forward = 0;
                lstForward.Clear();
                foreach (String strItem in m_CHeader.pstrKinematics)
                {
                    if (strItem != null)
                    {
                        if (strItem.Length > 0)
                        {
                            CKinematics.CForward.MakeDhParam(strItem, out m_CHeader.pDhParamAll[nPos]);
                            m_nCnt_Forward++;
                            lstForward.Add(nPos);
                        }
                    }
                    nPos++;
                }
            }
            public void CheckInverse()
            {
                int nPos = 0;
                int nCnt_InverseKinematics = 0;
                m_nCnt_Inverse = 0;
                lstInverse.Clear();
                foreach (String strItem in m_CHeader.pstrInverseKinematics)
                {
                    if (strItem != null)
                    {
                        if (strItem.Length > 0)
                        {
                            CKinematics.CInverse.Compile(((m_CHeader.pbPython[nPos] == true) ? "!": string.Empty) + strItem, out m_CHeader.pSOjwCode[nPos]);                            
                            m_nCnt_Inverse++;
                            lstInverse.Add(nPos);
                        }
                    }
                    if (m_CHeader.pSOjwCode[nPos].nMotor_Max > 0) nCnt_InverseKinematics++;
                    nPos++;
                }
                m_nCnt_InverseKinematics = nCnt_InverseKinematics;
            }
            public bool IsInverseFunction(int nFuncNum) { if (m_CHeader.pstrInverseKinematics != null) { if (m_CHeader.pstrInverseKinematics.Length > 0) return true; } return false; }
            private int m_nCnt_InverseKinematics = 0;

            #region 문자열 길이 필드 (버전 01.09.00 부터 4바이트)
            // .ojw 의 Kinematics / InverseKinematics 길이는 2바이트(short, 최대 32,767),
            // DrawModel 길이는 2바이트(ushort, 최대 65,535) 였다.
            // DH 모델링 텍스트가 이 한계를 넘으면 캐스팅에서 값이 잘려 로드 시 스트림이 어긋났다.
            //
            // 01.09.00 부터 세 필드 모두 4바이트(int32) 로 기록한다.
            // 구형식(01.08.00 이하) 파일은 로드 시 버전 분기로 예전처럼 2바이트를 읽으므로 그대로 열린다.
            //   → Center_Evd / MechMove 를 16비트에서 32비트로 넓힌 01.02.00 과 같은 방식.
            // 구버전 빌드에서 열어야 하면 FileSave(..., _STR_EXT_VERSION_LEGACY) 로 저장한다.
            //
            // ReadStringLength_Legacy 의 (short)-1 확장 표식은 01.09.00 도입 전 잠시 쓰던
            // 인라인 확장 인코딩의 잔재다. 그 형식으로 저장된 파일도 계속 읽히도록 남겨둔다.
            // (정상적인 구형식 파일은 길이가 항상 0 이상이라 -1 이 나올 수 없어 충돌하지 않는다.)
            private static void WriteStringLength(FileStream fs, int nVersion, int nLength)
            {
                byte[] byteLen;
                if (nVersion >= 010900)
                {
                    byteLen = BitConverter.GetBytes(nLength);          // 4 Bytes
                    fs.Write(byteLen, 0, 4);
                }
                else
                {
                    byteLen = BitConverter.GetBytes((short)(nLength)); // 2 Bytes (구형식)
                    fs.Write(byteLen, 0, 2);
                }
            }
            private static int ReadStringLength(byte[] byteData, ref int nPos, int nVersion)
            {
                if (nVersion >= 010900)
                {
                    int nLength = BitConverter.ToInt32(byteData, nPos);
                    nPos += 4;
                    return nLength;
                }
                return ReadStringLength_Legacy(byteData, ref nPos);
            }
            private static int ReadStringLength_Legacy(byte[] byteData, ref int nPos)
            {
                int nLength = (int)(short)(BitConverter.ToInt16(byteData, nPos));
                nPos += 2;
                if (nLength == -1)                                     // 과도기 확장 표식
                {
                    nLength = BitConverter.ToInt32(byteData, nPos);
                    nPos += 4;
                }
                return nLength;
            }
            // DrawModel 은 구형식이 부호 없는 ushort 였다 (최대 65,535).
            private static void WriteStringLength_DrawModel(FileStream fs, int nVersion, int nLength)
            {
                byte[] byteLen;
                if (nVersion >= 010900)
                {
                    byteLen = BitConverter.GetBytes(nLength);           // 4 Bytes
                    fs.Write(byteLen, 0, 4);
                }
                else
                {
                    byteLen = BitConverter.GetBytes((ushort)(nLength)); // 2 Bytes (구형식)
                    fs.Write(byteLen, 0, 2);
                }
            }
            private static int ReadStringLength_DrawModel(byte[] byteData, ref int nPos, int nVersion)
            {
                int nLength;
                if (nVersion >= 010900)
                {
                    nLength = BitConverter.ToInt32(byteData, nPos);
                    nPos += 4;
                }
                else
                {
                    nLength = (int)(ushort)(BitConverter.ToUInt16(byteData, nPos));
                    nPos += 2;
                }
                return nLength;
            }

